        $m(2,'single_choice','Khoanh vùng nguyên nhân','Log hệ thống cho thấy lượng lỗi tăng đột biến sau bản cập nhật đăng nhập sáng nay.',[$c('So sánh các dòng code thay đổi (diff) và viết unit test tái hiện lỗi',3,'Phương pháp khoa học! Test giúp xác định đúng lỗi và ngăn lỗi tái phát.',['analysis'=>3,'precision'=>3],0),$c('Sửa nóng một dòng code trông có vẻ đáng ngờ trực tiếp trên server thật',0,'Sửa nóng khi chưa kiểm chứng dễ tạo ra lỗi dây chuyền thảm khốc.',['decision'=>0],1),$c('Kết luận ngay do mạng của trường chập chờn mà không kiểm tra log',0,'Đổ lỗi khi thiếu bằng chứng làm chậm tiến độ và giảm uy tín đội kỹ thuật.',['empathy'=>0],2)],'Thay đổi gần nhất luôn là manh mối đầu tiên đáng kiểm tra.'),
        $m(2,'priority_order','Quy trình điều tra lỗi cơ sở dữ liệu','Có nghi vấn câu lệnh truy vấn điểm danh bị nghẽn (deadlock) khi hàng trăm lớp cùng gửi.',[$c('1. Bật log truy vấn chậm -> 2. Đo thời gian phản hồi câu lệnh -> 3. Đánh index tối ưu',3,'Xuất sắc! Bạn tuân thủ đúng quy trình tối ưu cơ sở dữ liệu chuyên nghiệp.',['precision'=>3,'analysis'=>3],0),$c('1. Đánh index bừa bãi -> 2. Xóa bớt dữ liệu điểm danh -> 3. Kiểm tra log',1,'Đánh index thiếu tính toán có thể làm chậm thao tác ghi dữ liệu.',['decision'=>1],1),$c('1. Nâng cấp gói máy chủ đắt tiền nhất -> 2. Không cần xem lại câu lệnh',0,'Tăng phần cứng chỉ che giấu lỗi code kém hiệu quả và tốn chi phí.',['analysis'=>0],2)],'Quy trình chuẩn: Đo lường -> Khoanh vùng -> Tối ưu hóa.'),
        $m(3,'single_choice','Chọn phương án phát hành gấp','Bạn đã tìm ra bản vá nhưng chỉ còn 8 phút là vào tiết 1.',[$c('Review nhanh với đồng nghiệp, chạy test tự động chính rồi deploy kèm script quay lui',3,'Cân bằng hoàn hảo giữa tốc độ và an toàn vận hành hệ thống.',['decision'=>3,'precision'=>3,'analysis'=>2],0),$c('Deploy ngay lập tức lên server vì thấy \'trên máy mình chạy tốt\'',1,'Quá liều lĩnh! Môi trường cá nhân khác biệt lớn với server phục vụ hàng nghìn người.',['decision'=>1],1),$c('Chờ đến cuối ngày học mới sửa, để giáo viên ghi sổ tay cả ngày',1,'An toàn quá mức làm giảm giá trị ứng dụng và gây phiền hà lớn cho người dùng.',['empathy'=>1],2)],'Khi triển khai gấp, luôn chuẩn bị sẵn kế hoạch rollback (quay lui).'),
        $m(3,'trade_off','Đánh đổi giữa tính năng và tải máy chủ','Nếu tạm tắt ảnh đại diện học sinh, tốc độ tải app sẽ tăng gấp 4 lần trong giờ cao điểm.',[$c('Tạm thời tắt ảnh trong 1 giờ cao điểm đầu ngày (Ưu tiên: Tốc độ và thông suốt)',3,'Quyết định thực dụng tuyệt vời để đảm bảo mục tiêu cốt lõi: điểm danh đúng giờ.',['decision'=>3,'analysis'=>2],0),$c('Giữ nguyên ảnh và nén độ phân giải cực nhỏ trước khi gửi (Ưu tiên: Giữ trải nghiệm thị giác)',2,'Bảo vệ trải nghiệm người dùng nhưng tốn thêm CPU máy chủ để nén ảnh.',['creativity'=>2,'precision'=>2],1),$c('Giữ nguyên tất cả và giới hạn số lượng lớp được điểm danh cùng lúc',1,'Tạo ra cảnh xếp hàng chờ đợi khó chịu cho các lớp vào sau.',['empathy'=>1],2)],'Mỗi quyết định kỹ thuật đều là sự cân bằng giữa trải nghiệm và độ ổn định.'),
