        $m(4,'trade_off','Bảo mật dữ liệu học sinh','Một giáo viên nhờ bạn xuất danh sách số điện thoại phụ huynh qua file Excel không đặt mật khẩu.',[$c('Giải thích quy định bảo mật, hỗ trợ xuất file mã hóa gửi qua email nội bộ trường (Ưu tiên: An toàn dữ liệu & Tôn trọng)',3,'Rất chuẩn mực! Bạn vừa bảo vệ an toàn thông tin vừa hỗ trợ công việc khéo léo.',['precision'=>3,'empathy'=>3,'decision'=>2],0),$c('Gửi ngay qua Zalo cá nhân vì giáo viên đang cần gấp (Ưu tiên: Tốc độ trước mắt)',0,'Vi phạm nghiêm trọng an toàn dữ liệu và quyền riêng tư của phụ huynh.',['precision'=>0],1),$c('Từ chối thẳng thừng và báo cáo kỷ luật giáo viên (Ưu tiên: Nguyên tắc cứng nhắc)',1,'Bảo vệ nguyên tắc nhưng làm rạn nứt quan hệ phối hợp trong nhà trường.',['empathy'=>0],2)],'Kỹ sư công nghệ phải là người gác cổng bảo vệ quyền riêng tư dữ liệu.')
