    'ky-su-tri-tue-nhan-tao' => $game('Huấn luyện AI phân loại rác','Kỹ sư AI tập sự','Trường muốn lắp camera nhận diện rác tái chế. Bạn cần tạo mô hình vừa chính xác, vừa công bằng và an toàn.','AI Lab · Dataset 2.400 ảnh',[
        $m(1,'single_choice','Kiểm tra tập dữ liệu ban đầu','Bộ ảnh gồm 2.000 ảnh chai nhựa, nhưng chỉ có 50 ảnh pin và đồ điện tử.',[$c('Thống kê phân bố các nhãn, bổ sung ảnh thu thập thực tế cho nhóm thiếu',3,'Chính xác! Dữ liệu cân bằng giúp mô hình học đúng bản chất thay vì thiên lệch.',['analysis'=>3,'precision'=>3],0),$c('Bấm huấn luyện ngay vì tổng số ảnh 2.000 đã là con số khá lớn',1,'Tổng số lớn nhưng bị lệch nhãn sẽ khiến AI bỏ qua các loại rác nguy hiểm.',['decision'=>1],1),$c('Nhân bản 50 ảnh pin lên 40 lần bằng cách copy paste',1,'Nhân bản thô dễ khiến mô hình bị học vẹt (overfitting) các góc chụp cũ.',['analysis'=>1],2)],'Chất lượng và tính đại diện của dữ liệu quyết định năng lực mô hình.'),
        $m(1,'trade_off','Chiến lược gán nhãn dữ liệu','Ngân sách có hạn, bạn cần gán nhãn 1.000 ảnh rác mới thu thập từ sân trường.',[$c('Huy động câu lạc bộ môi trường cùng gán nhãn có hướng dẫn chuẩn (Ưu tiên: Giáo dục cộng đồng & Tiết kiệm)',3,'Vừa có nhãn thực tế vừa lan tỏa ý thức phân loại rác cho học sinh.',['empathy'=>3,'creativity'=>2,'decision'=>2],0),$c('Dùng mô hình AI mã nguồn mở tự động gán nhãn rồi kiểm tra xác suất (Ưu tiên: Tốc độ tối đa)',2,'Nhanh chóng nhưng nếu AI nguồn mở gán sai, lỗi sẽ nhân bản vào tập dữ liệu.',['analysis'=>2,'precision'=>2],1),$c('Tự một mình ngồi gán nhãn cả 1.000 ảnh trong đêm (Ưu tiên: Tự chủ tuyệt đối)',1,'Độ chính xác cao lúc đầu nhưng mệt mỏi sẽ dẫn đến sai sót dây chuyền.',['precision'=>1],2)],'Đánh đổi giữa chi phí, thời gian và độ chính xác của nhãn huấn luyện.'),
        $m(2,'single_choice','Đánh giá ma trận nhầm lẫn (Confusion Matrix)','Độ chính xác chung đạt 94%, nhưng lớp rác Pin nguy hại chỉ nhận diện đúng 52%.',[$c('Phân tích ma trận nhầm lẫn, ưu tiên thu thập và phạt nặng lỗi bỏ sót pin',3,'Tư duy kỹ sư AI thực thụ! Bạn nhìn sâu hơn con số hào nhoáng 94%.',['analysis'=>3,'precision'=>3,'empathy'=>2],0),$c('Báo cáo với nhà trường độ chính xác 94% và đưa vào sử dụng ngay',0,'Con số trung bình đã che giấu rủi ro cháy nổ do pin bị phân loại sai.',['decision'=>0],1),$c('Xóa luôn nhãn pin ra khỏi bài toán để số liệu báo cáo đẹp hơn',0,'Trốn tránh vấn đề cốt lõi của bài toán phân loại rác học đường.',['decision'=>0],2)],'Một mô hình giỏi phải an toàn ở những trường hợp rủi ro cao nhất.'),
        $m(2,'priority_order','Quy trình tinh chỉnh siêu tham số (Hyperparameters)','Mô hình bị hiện tượng quá khớp (Overfitting): điểm tập train 99% nhưng test chỉ 60%.',[$c('1. Tăng cường dữ liệu (Data Augmentation) -> 2. Thêm Dropout/Weight Decay -> 3. Đánh giá trên tập Validation',3,'Tuyệt vời! Đây là giáo trình chuẩn của kỹ sư Deep Learning hiện đại.',['precision'=>3,'analysis'=>3],0),$c('1. Cho train thêm 500 epoch -> 2. Tăng kích thước mạng lớn hơn -> 3. Không cần kiểm tra validation',0,'Càng huấn luyện lâu mạng càng học vẹt nặng hơn.',['analysis'=>0],1),$c('1. Đổi bừa bộ dữ liệu khác -> 2. Hy vọng kết quả tự tốt lên',0,'Thiếu phương pháp luận khoa học trong nghiên cứu AI.',['decision'=>0],2)],'Quy trình chuẩn: Giảm độ phức tạp -> Tăng cường dữ liệu -> Regularization.'),
        $m(3,'trade_off','Thiết kế trải nghiệm khi AI không chắc chắn','Camera chụp một chiếc cốc giấy dính nhựa, AI chỉ tự tin 51% cốc giấy và 49% nhựa.',[$c('Hiển thị 2 lựa chọn lên màn hình cảm ứng để học sinh tự bấm chọn (Ưu tiên: Con người làm chủ & Học dữ liệu mới)',3,'Thiết kế AI nhân bản (Human-in-the-loop)! Vừa chính xác vừa thu thập thêm dữ liệu khó.',['empathy'=>3,'creativity'=>2,'decision'=>3],0),$c('Luôn tự động mở nắp thùng giấy theo xác suất cao hơn (Ưu tiên: Tự động hóa hoàn toàn)',1,'Nhanh nhưng tạo cảm giác AI độc đoán và dễ gây nhiễm bẩn rác tái chế.',['decision'=>1],1),$c('Báo chuông báo động đỏ và khóa toàn bộ thùng rác lại (Ưu tiên: Cảnh báo cực đoan)',0,'Gây ức chế khiến học sinh không muốn sử dụng thùng rác thông minh nữa.',['empathy'=>0],2)],'Khi AI không chắc chắn, hãy trao quyền kiểm soát và học hỏi từ con người.'),
        $m(3,'single_choice','Lựa chọn phần cứng triển khai tại biên (Edge AI)','Mô hình siêu lớn chạy trên server thì cực thông minh nhưng tốn tiền mạng và trễ 3 giây.',[$c('Lượng tử hóa (Quantization) và tối ưu mô hình nhẹ chạy trực tiếp trên chip nhúng tại thùng rác',3,'Tối ưu hóa tuyệt vời! Phản hồi tức thì trong 0.1 giây mà không cần Internet liên tục.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('Bắt buộc trường phải kéo cáp quang riêng đến từng thùng rác ngoài trời',1,'Chi phí thi công quá lớn, không khả thi trong môi trường trường học.',['decision'=>1],1),$c('Chỉ dùng cảm biến hồng ngoại đơn giản và bỏ hoàn toàn camera AI',1,'Bỏ cuộc quá sớm trước một bài toán công nghệ có thể giải quyết được.',['creativity'=>1],2)],'Cân bằng giữa độ phức tạp mô hình và tài nguyên tính toán thực tế.'),
        $m(4,'single_choice','Quyền riêng tư hình ảnh học sinh','Camera thùng rác vô tình chụp rõ khuôn mặt học sinh khi vứt rác.',[$c('Cắt xén vùng ảnh chỉ lấy bàn tay và rác, tự động làm mờ khuôn mặt ngay trên bộ nhớ đệm trước khi lưu',3,'Chuẩn mực đạo đức AI quốc tế! Bảo vệ tuyệt đối quyền riêng tư của trẻ vị thành niên.',['precision'=>3,'empathy'=>3,'decision'=>3],0),$c('Lưu nguyên ảnh khuôn mặt và tạo bảng xếp hạng học sinh vứt rác lên cổng trường',0,'Vi phạm nghiêm trọng quyền bảo vệ hình ảnh học sinh và gây áp lực tâm lý tiêu cực.',['empathy'=>0],1),$c('Giữ nguyên khuôn mặt nhưng hứa sẽ không ai xem ảnh',0,'Lời hứa suông không thay thế được các biện pháp an ninh kỹ thuật.',['precision'=>0],2)],'Đạo đức AI: Thu thập tối thiểu và bảo vệ danh tính cá nhân bằng công nghệ.'),
        $m(4,'trade_off','Kế hoạch thử nghiệm diện rộng (Pilot)','Hiệu trưởng muốn nhân rộng ra 50 thùng rác toàn trường ngay tuần sau.',[$c('Đề xuất thử trước tại 3 thùng ở căng tin trong 2 tuần để đo lỗi và cải tiến (Ưu tiên: An toàn & Học hỏi)',3,'Thuyết phục dựa trên căn cứ khoa học, giảm thiểu rủi ro lãng phí ngân sách trường.',['decision'=>3,'analysis'=>2,'empathy'=>2],0),$c('Đồng ý lắp ngay 50 thùng để lấy thành tích nghiên cứu (Ưu tiên: Danh tiếng nhanh chóng)',1,'Rủi ro vận hành cực cao, nếu mô hình lỗi sẽ làm hỏng toàn bộ dự án.',['decision'=>0],1),$c('Từ chối vì cho rằng mô hình AI không bao giờ đạt độ hoàn hảo 100%',1,'Chủ nghĩa cầu toàn làm mất cơ hội đưa nghiên cứu ứng dụng vào cuộc sống.',['analysis'=>1],2)],'Thử nghiệm có kiểm soát (Pilot) là cầu nối an toàn giữa phòng lab và đời thực.')
    ],['title'=>'Thử nghiệm Prompt Engineering & Nhận diện thiên kiến','duration'=>'15 phút','action'=>'Dùng một công cụ AI miễn phí (như Gemini/ChatGPT), thử đưa cùng 1 bài toán nhưng thay đổi 3 cách diễn đạt khác nhau (ngắn gọn, chi tiết kèm vai trò, và câu hỏi có bẫy). Ghi lại điểm khác biệt trong câu trả lời.','reflection_question'=>'Bạn có nhận thấy AI phụ thuộc hoàn toàn vào cách con người định hình câu hỏi và dữ liệu đầu vào không?']),
    'bac-si' => $game('Ca trực phòng khám học đường','Bác sĩ trực','Một học sinh chóng mặt sau giờ thể dục. Bạn cần đánh giá an toàn, giao tiếp bình tĩnh và quyết định bước tiếp theo.','Phòng y tế · 10:25',[
        $m(1,'single_choice','Đánh giá an toàn ban đầu (ABC)','Học sinh mặt tái, hơi run rẩy nhưng vẫn tỉnh táo khi bước vào phòng y tế.',[$c('Đỡ em nằm xuống giường thoáng mát, đo mạch, huyết áp, nhịp thở và SpO2 ngay',3,'Xử trí chuẩn y khoa! Đánh giá dấu hiệu sinh tồn khách quan trước mọi kết luận.',['precision'=>3,'analysis'=>3,'empathy'=>2],0),$c('Cho uống ngay một viên thuốc giảm đau hạ sốt',0,'Cho dùng thuốc khi chưa khám là hành vi nguy hiểm có thể che lấp triệu chứng cấp tính.',['decision'=>0],1),$c('Bảo học sinh ngồi ghế ngoài hành lang nghỉ một lát rồi về lớp',0,'Chủ quan bỏ qua nguy cơ hạ đường huyết hoặc chấn thương tiềm ẩn.',['empathy'=>0],2)],'Trong y khoa, luôn kiểm tra đường thở, nhịp thở và tuần hoàn đầu tiên.'),
        $m(1,'trade_off','Giao tiếp trấn an tâm lý học sinh','Học sinh rất lo lắng, sợ bị ngất và sợ bị ghi tên vào sổ kỷ luật nghỉ học.',[$c('Nói giọng trầm ấm: \'Bác sĩ ở đây rồi, em an toàn nhé. Nghỉ ngơi là ưu tiên số một.\' (Ưu tiên: Trấn an cảm xúc)',3,'Thái độ nhân từ giúp hạ nhịp tim học sinh và tạo sự hợp tác điều trị.',['empathy'=>3,'decision'=>2],0),$c('Hỏi dồn dập các câu hỏi kỹ thuật về tiền sử bệnh (Ưu tiên: Thu thập dữ liệu nhanh)',1,'Lấy được thông tin nhưng làm học sinh thêm căng thẳng và huyết áp tăng.',['analysis'=>2,'precision'=>1],1),$c('Bảo bạn bè đi cùng ra ngoài hết và đóng cửa phòng lại (Ưu tiên: Không gian yên tĩnh)',2,'Tạo không gian tĩnh nhưng cần giải thích nhẹ nhàng để các em không sợ hãi.',['precision'=>2,'empathy'=>1],2)],'Thấu cảm và lắng nghe là liều thuốc xoa dịu nỗi sợ đầu tiên của bệnh nhân.'),
        $m(2,'single_choice','Khai thác bệnh sử có cấu trúc','Em cho biết sáng nay vội đi học nên chưa ăn sáng và vừa chạy kiểm tra 1.500m.',[$c('Hỏi thêm về tiền sử tim mạch, tiền sử ngất, lượng nước đã uống và cảm giác cồn cào',3,'Chẩn đoán phân biệt sắc bén! Giúp phân biệt hạ đường huyết, kiệt sức do nhiệt hay rối loạn nhịp tim.',['analysis'=>3,'precision'=>3,'empathy'=>2],0),$c('Khẳng định chắc chắn 100% chỉ là đói bụng đơn thuần',1,'Đó là khả năng cao nhất nhưng khẳng định quá sớm khi chưa loại trừ các nguyên nhân khác.',['analysis'=>1],1),$c('Nghi ngờ em giả ốm để trốn tiết thể dục',0,'Định kiến thiếu đạo đức y khoa, gây tổn thương niềm tin người bệnh.',['empathy'=>0],2)],'Hỏi bệnh sử có hệ thống: Bệnh nền, dị ứng, thời điểm xuất hiện và diễn tiến.'),
        $m(2,'priority_order','Quy trình sơ cứu hạ đường huyết nhẹ','Dấu hiệu sinh tồn ổn định, test nhanh đường huyết mao mạch hơi thấp (3.2 mmol/L).',[$c('1. Cho uống 1 cốc nước đường/nước hoa quả ấm -> 2. Nằm nghỉ theo dõi 15 phút -> 3. Kiểm tra lại triệu chứng và đường huyết',3,'Chính xác tuyệt đối! Xử trí đúng phác đồ điều trị quốc tế.',['precision'=>3,'decision'=>3,'analysis'=>2],0),$c('1. Cho ăn ngay một tô phở nhiều thịt -> 2. Vận động nhẹ nhàng -> 3. Cho về lớp',1,'Thức ăn nhiều đạm mỡ tiêu hóa chậm, không nâng đường huyết cấp cứu kịp thời.',['analysis'=>1],1),$c('1. Tiêm truyền dịch tĩnh mạch ngay lập tức -> 2. Không cho ăn uống',0,'Can thiệp xâm lấn quá mức khi bệnh nhân vẫn tỉnh táo và uống được.',['decision'=>0],2)],'Quy tắc 15-15 trong xử trí hạ đường huyết: Bổ sung đường nhanh -> Nghỉ ngơi -> Đo lại.'),
        $m(3,'single_choice','Quy trình chuyển tuyến và theo dõi','Sau 20 phút bù nước đường, em tỉnh táo hoàn toàn, sắc mặt hồng hào trở lại.',[$c('Cho nghỉ thêm hết tiết học, liên hệ phụ huynh thông báo tình hình và dặn dò chế độ ăn sáng',3,'Quyết định nhân văn và cẩn trọng! Phối hợp chặt chẽ cùng gia đình bảo vệ sức khỏe học sinh.',['decision'=>3,'empathy'=>3,'precision'=>2],0),$c('Bắt buộc gọi xe cấp cứu 115 chở đi bệnh viện tuyến trên ngay',1,'Quá đà so với tình trạng hồi phục ổn định hiện tại, gây lãng phí và hoang mang.',['decision'=>1],1),$c('Bảo em lập tức quay lại sân chạy tiếp cho đủ điểm kiểm tra',0,'Hành vi vô trách nhiệm, đẩy học sinh vào nguy cơ tái phát ngất nguy hiểm.',['empathy'=>0],2)],'Cân nhắc mức độ can thiệp tương xứng và luôn có kế hoạch dự phòng.'),
        $m(3,'trade_off','Bàn giao cho giáo viên thể dục','Thầy thể dục rất sốt ruột và muốn biết học sinh có bị bệnh gì nghiêm trọng không.',[$c('Trao đổi với thầy về việc em cần nghỉ ngơi tiết này và lưu ý học sinh ăn sáng đủ (Ưu tiên: Hợp tác sư phạm & Bảo mật)',3,'Chia sẻ đúng phạm vi cần thiết để bảo vệ an toàn vận động mà không làm lộ bệnh án cá nhân.',['empathy'=>3,'precision'=>2,'decision'=>2],0),$c('Đưa toàn bộ phiếu theo dõi y tế cho thầy xem trước cả lớp (Ưu tiên: Minh bạch tuyệt đối)',1,'Xâm phạm quyền riêng tư hồ sơ sức khỏe của học sinh.',['precision'=>1],1),$c('Từ chối trả lời bất kỳ điều gì với thầy (Ưu tiên: Bí mật y khoa tuyệt đối)',1,'Tạo căng thẳng không đáng có và khiến thầy khó bố trí bài tập an toàn cho em.',['empathy'=>1],2)],'Bảo mật thông tin y tế cá nhân nhưng vẫn đảm bảo an toàn vận động.'),
        $m(4,'single_choice','Bảo mật thông tin sức khỏe học đường','Một số bạn cùng lớp tò mò đến hỏi bạn xem em kia \'có bị bệnh tim hay nghiện ngập gì không\'.',[$c('Nghiêm túc dặn các bạn tôn trọng bạn mình: \'Bạn chỉ mệt nhẹ và đang hồi phục tốt, các em về lớp nhé.\'',3,'Thái độ mực thước, dập tắt tin đồn thất thiệt và bảo vệ bạn học sinh.',['empathy'=>3,'precision'=>3,'decision'=>2],0),$c('Kể chi tiết chỉ số đường huyết và diễn biến bệnh cho các bạn nghe',0,'Vi phạm nghiêm trọng Luật Khám bệnh chữa bệnh và đạo đức y đức.',['precision'=>0],1),$c('Mắng mỏ xua đuổi các bạn học sinh',1,'Bảo vệ được thông tin nhưng cách hành xử chưa có tính giáo dục.',['empathy'=>1],2)],'Bảo mật thông tin bệnh nhân là lời thề danh dự của người thầy thuốc.'),
        $m(4,'trade_off','Giải pháp phòng ngừa bền vững cho nhà trường','Bạn nhận thấy trong tháng có tới 6 học sinh ngất vì nhịn ăn sáng khi chạy thể dục.',[$c('Đề xuất Ban giám hiệu tổ chức chuyên đề dinh dưỡng học đường và nhắc nhở thể dục đầu giờ (Ưu tiên: Giải pháp gốc rễ)',3,'Tầm nhìn y tế công cộng xuất sắc! Chữa bệnh từ căn nguyên trước khi sự cố xảy ra.',['analysis'=>3,'decision'=>3,'empathy'=>3],0),$c('Chỉ mua thêm nhiều túi đường dự trữ trong phòng y tế (Ưu tiên: Ứng phó bị động)',1,'Giải quyết tình thế nhưng học sinh vẫn tiếp tục bị ngất những tuần sau.',['analysis'=>1],1),$c('Đề xuất hủy bỏ hoàn toàn môn Giáo dục thể chất trong trường (Ưu tiên: Triệt tiêu nguy cơ)',0,'Giải pháp tiêu cực làm ảnh hưởng đến thể lực và phát triển thể chất của học sinh.',['decision'=>0],2)],'Y học dự phòng và giáo dục sức khỏe cộng đồng có giá trị gấp trăm lần điều trị.')
    ],['title'=>'Đo lường dấu hiệu sinh tồn cá nhân (Vital Signs)','duration'=>'15 phút','action'=>'Dùng 2 ngón tay đặt lên động mạch quay ở cổ tay hoặc động mạch cảnh ở cổ. Đếm nhịp tim trong 60 giây khi đang nghỉ ngơi, sau đó nhảy dây hoặc squat 20 cái và đo lại. Ghi chép sự thay đổi.','reflection_question'=>'Việc quan sát nhịp đập cơ thể có giúp bạn cảm nhận rõ hơn về sự sống và sự kỳ diệu của sinh học người không?']),
    'nha-thiet-ke-do-hoa' => $game('Thiết kế poster lễ hội xanh','Nhà thiết kế đồ họa','Bạn nhận brief làm poster cho ngày hội tái chế. Poster phải nổi bật, dễ đọc và đúng tinh thần học sinh.','Creative Studio · Deadline 16:00',[
        $m(1,'single_choice','Giải mã bản yêu cầu (Creative Brief)','Khách hàng gửi 3 trang văn bản đặc kín chữ và yêu cầu \'đưa tất cả lên poster A2\'.',[$c('Phân tích xác định 1 thông điệp chính, đối tượng mục tiêu và hành động kêu gọi (Call to action)',3,'Tư duy thiết kế chuyên nghiệp! Bạn biến mớ hỗn độn thành mục tiêu thị giác rõ nét.',['analysis'=>3,'empathy'=>2,'creativity'=>2],0),$c('Thu nhỏ cỡ chữ xuống 6pt để nhồi nhét đủ toàn bộ 3 trang văn bản',0,'Đủ chữ nhưng biến poster thành tờ công báo, không ai có thể đọc được từ xa.',['precision'=>1],1),$c('Bỏ qua yêu cầu và tự vẽ những hình ảnh trừu tượng mình thích',1,'Sáng tạo cá nhân nhưng không giải quyết bài toán truyền thông của khách hàng.',['creativity'=>2],2)],'Thiết kế bắt đầu từ việc gạn lọc thông điệp truyền thông cốt lõi.'),
        $m(1,'trade_off','Nghiên cứu thị trường và Moodboard','Bạn có 45 phút để chuẩn bị phong cách trước khi phác thảo.',[$c('Tạo Moodboard kết hợp màu sắc tươi sáng, thân thiện môi trường của thế hệ Gen Z (Ưu tiên: Đúng gu đối tượng)',3,'Định hướng thị giác chuẩn xác, tạo sự đồng cảm sâu sắc với học sinh.',['empathy'=>3,'creativity'=>3],0),$c('Sao chép nguyên phong cách poster bảo vệ môi trường thập niên 90 (Ưu tiên: Hoài niệm cổ điển)',1,'Có nét riêng nhưng có thể bị xem là lỗi thời và xa lạ với giới trẻ hiện đại.',['creativity'=>1],1),$c('Không làm moodboard mà mở phần mềm vẽ ngay (Ưu tiên: Tốc độ cơ học)',1,'Bắt tay vào làm ngay nhưng dễ bị bế tắc ý tưởng giữa chừng.',['decision'=>1],2)],'Đánh đổi giữa cảm hứng mới lạ và độ quen thuộc với học sinh.'),
        $m(2,'single_choice','Phác thảo concept sơ bộ (Thumbnail Sketches)','Chủ đề là \'Một chai nhựa, một vòng đời mới\'.',[$c('Vẽ nhanh 4-5 bản phác thảo layout bố cục (thumnail) để so sánh góc nhìn trước khi vẽ máy',3,'Quy trình thiết kế chuẩn mực quốc tế! Khám phá đa chiều trước khi đổ công sức chi tiết.',['creativity'=>3,'analysis'=>2,'precision'=>2],0),$c('Tải một vector có sẵn trên mạng về đổi màu rồi gửi duyệt',0,'Thiếu sáng tạo nguyên bản và tiềm ẩn rủi ro vi phạm bản quyền thương mại.',['creativity'=>0],1),$c('Chỉ vẽ đúng một ý tưởng duy nhất rồi tô màu tỉ mỉ suốt 3 tiếng',1,'Dồn hết trứng vào một giỏ, nếu khách hàng không ưng sẽ phải làm lại từ đầu.',['decision'=>1],2)],'Phác thảo nhanh nhiều ý tưởng rẻ hơn sửa file hoàn thiện rất nhiều.'),
        $m(2,'priority_order','Quy trình thiết lập hệ thống phân cấp thị giác (Hierarchy)','Poster có quá nhiều yếu tố tranh giành sự chú ý khiến mắt người xem bị loạn.',[$c('1. Tạo điểm nhấn thị giác chính (Key Visual) -> 2. Phân tầng cỡ chữ (Header/Body) -> 3. Cân bằng khoảng trống (Negative Space)',3,'Bố cục hoàn hảo! Mắt người xem được dẫn dắt mượt mà từ tiêu đề đến lời kêu gọi.',['precision'=>3,'creativity'=>3,'analysis'=>2],0),$c('1. Phóng to tất cả mọi thứ -> 2. Đổi mỗi dòng một màu khác nhau -> 3. Không chừa khoảng trống nào',0,'Biến poster thành một \'nồi lẩu thập cẩm\' gây mỏi mắt và rối loạn thông tin.',['creativity'=>0],1),$c('1. Làm tiêu đề thật mờ nhạt -> 2. Làm logo nhà tài trợ to nhất',1,'Khán giả chỉ nhớ logo mà hoàn toàn không hiểu sự kiện là gì.',['decision'=>1],2)],'Quy tắc: Điểm nhìn tiêu điểm (Focal Point) -> Phân cấp chữ -> Khoảng trống thở.'),
        $m(3,'trade_off','Kiểm tra độ tương phản và khả năng đọc (Readability)','Poster xem trên màn hình OLED rất rực rỡ nhưng in thử ra giấy bị tối và khó đọc.',[$c('Chuyển hệ màu sang CMYK, tăng tương phản giữa chữ và nền (Ưu tiên: Khả năng đọc thực tế khi in)',3,'Kỹ năng tiền kỳ in ấn (Pre-press) xuất sắc! Đảm bảo tác phẩm đẹp cả trên mạng lẫn trên tường.',['precision'=>3,'analysis'=>2,'decision'=>2],0),$c('Giữ nguyên màu RGB vì màu này trông \'nghệ thuật\' hơn trên máy tính (Ưu tiên: Cảm xúc cá nhân)',1,'Bảo vệ cái tôi nhưng sản phẩm in ra bị sai màu và thất bại trong việc truyền tin.',['creativity'=>1],1),$c('Thêm hiệu ứng viền phát sáng (Glow) quanh mọi chữ cái (Ưu tiên: Giải pháp tạm bợ)',1,'Chữa cháy thô vụng khiến thiết kế bị cũ kỹ và giảm độ sang trọng.',['creativity'=>1],2)],'Thiết kế thực tế luôn phải tính đến bối cảnh hiển thị và công nghệ in ấn.'),
        $m(3,'single_choice','Tiếp nhận phản hồi từ khách hàng (Feedback)','Khách hàng muốn: \'Logo nhà tài trợ to gấp đôi, thêm màu đỏ và đổi giờ sự kiện\'.',[$c('Cập nhật giờ, đề xuất vị trí đặt logo trang trọng ở dải chân trang (footer) vừa nổi bật vừa giữ cân bằng',3,'Giao tiếp tinh tế và chuyên nghiệp! Bạn bảo vệ tính thẩm mỹ mà khách hàng vẫn hài lòng.',['empathy'=>3,'decision'=>3,'precision'=>2],0),$c('Phản ứng gay gắt: \'Khách hàng không có gu, tôi từ chối sửa!\'',0,'Cư xử thiếu chuyên nghiệp, phá vỡ mối quan hệ hợp tác công việc.',['empathy'=>0],1),$c('Khách bảo sao làm y hệt vậy mà không góp ý chuyên môn gì',1,'Trở thành người thợ bấm máy thụ động thay vì một chuyên gia tư vấn thiết kế.',['creativity'=>1],2)],'Designer giỏi biết lắng nghe nhu cầu cốt lõi đằng sau những lời yêu cầu vô lý.'),
        $m(4,'single_choice','Tôn trọng bản quyền tác giả hình ảnh','Bạn thấy một bức ảnh minh họa chú rùa biển rất đẹp trên mạng nhưng không rõ nguồn gốc.',[$c('Tự tay vẽ lại một hình minh họa độc bản hoặc mua ảnh có bản quyền thương mại rõ ràng',3,'Rất đáng tự hào! Bạn bảo vệ an toàn pháp lý cho dự án và tôn trọng công sức người khác.',['precision'=>3,'creativity'=>3,'decision'=>2],0),$c('Cắt bỏ chữ ký của tác giả rồi dùng luôn vì nghĩ \'làm cho trường học thì không sao\'',0,'Hành vi vi phạm luật bản quyền sở hữu trí tuệ, có thể gây scandal truyền thông.',['decision'=>0],1),$c('Chỉ đổi màu chú rùa rồi nhận là tác phẩm của mình',0,'Đạo nhái ý tưởng là vết nhơ lớn nhất trong sự nghiệp của nhà thiết kế.',['creativity'=>0],2)],'Đạo đức nghề nghiệp: Tôn trọng tài sản trí tuệ của đồng nghiệp sáng tạo.'),
        $m(4,'trade_off','Bàn giao file in ấn chuẩn kỹ thuật','Xưởng in yêu cầu gửi file trước 16:00 để kịp tiến độ sự kiện sáng mai.',[$c('Khóa font (Create Outlines), bù xén mép (Bleed 3mm), xuất file PDF Print chất lượng cao (Ưu tiên: Chuẩn kỹ thuật xưởng in)',3,'Tuyệt vời! Xưởng in nhận file in được ngay mà không bị lỗi nhảy font hay mất mép viền.',['precision'=>3,'decision'=>2],0),$c('Chụp màn hình gửi qua Zalo rồi giục xưởng in tự xử lý (Ưu tiên: Tiện tay)',0,'Ảnh bị nén mờ căm, poster in ra bị vỡ hạt không thể dùng được.',['precision'=>0],1),$c('Chỉ gửi file ảnh JPG chất lượng thấp để file nhẹ gửi cho nhanh',1,'File nhẹ nhưng màu sắc và chữ in sẽ bị răng cưa mờ nhạt.',['analysis'=>1],2)],'Sự tỉ mỉ ở khâu đóng gói file (Packaging) quyết định chất lượng thành phẩm cuối cùng.')
    ],['title'=>'Săn lùng Typography & Phân cấp thị giác','duration'=>'15 phút','action'=>'Tìm một bìa sách hoặc bao bì sản phẩm quanh phòng bạn. Nhận diện 3 cấp độ chữ (Tiêu đề chính lớn nhất, Phụ đề giải thích, và Thông tin chi tiết nhỏ nhất). Chụp ảnh hoặc ghi lại điểm mắt bạn chú ý đầu tiên.','reflection_question'=>'Bạn có nhận ra mắt người luôn bị dẫn dắt bởi kích thước và độ tương phản của chữ không?']),
    'giao-vien' => $game('Tiết học đánh thức lớp','Giáo viên chủ nhiệm','Bạn có 35 phút dạy chủ đề biến đổi khí hậu cho một lớp có mức độ tiếp thu rất khác nhau.','Lớp 9A · Tiết 3',[
        $m(1,'single_choice','Mở đầu bài học lôi cuốn','Nhiều học sinh còn uể oải, mất tập trung sau giờ ra chơi.',[$c('Đưa bức ảnh sân trường ngập nước tuần trước và hỏi: \'Tại sao nước dâng cao hơn 5 năm trước?\'',3,'Mở đầu bài giảng xuất sắc! Gắn liền tri thức sách vở với hiện tượng đời sống học sinh chứng kiến.',['creativity'=>3,'empathy'=>2,'analysis'=>2],0),$c('Đọc to từng chữ định nghĩa biến đổi khí hậu trong sách giáo khoa',1,'Đúng nội dung nhưng khô khan, dễ khiến học sinh chìm vào giấc ngủ.',['precision'=>1],1),$c('Bất ngờ gọi tên kiểm tra bài cũ để cả lớp giật mình sợ hãi',1,'Tạo sự tập trung bằng nỗi sợ thay vì sự say mê học tập tự nhiên.',['decision'=>1],2)],'Một câu hỏi tình huống thực tế có sức mạnh đánh thức tò mò tốt hơn mệnh lệnh.'),
        $m(1,'trade_off','Phân chia không gian và năng lượng lớp học','Một số bạn ngồi bàn cuối thường xuyên làm việc riêng và ngại phát biểu.',[$c('Di chuyển xuống cuối lớp giảng bài, đặt câu hỏi gợi mở cho nhóm bàn dưới (Ưu tiên: Kéo học sinh hòa nhập)',3,'Sự hiện diện gần gũi của giáo viên giúp học sinh cảm thấy được quan tâm và tập trung lại.',['empathy'=>3,'decision'=>2],0),$c('Chỉ tập trung trao đổi với các bạn học sinh giỏi ngồi bàn đầu (Ưu tiên: Tiến độ trôi chảy)',1,'Tiết học diễn ra rất nhanh nhưng khoảng cách trong lớp ngày càng bị nới rộng.',['analysis'=>1],1),$c('Ghi tên các bạn bàn cuối lên góc bảng để trừ điểm thi đua (Ưu tiên: Kỷ luật hành chính)',1,'Biện pháp răn đe hành chính không khơi dậy được động lực học tập bên trong.',['empathy'=>0],2)],'Người thầy giỏi không bỏ quên bất kỳ học sinh nào ở góc khuất.'),
        $m(2,'single_choice','Phân hóa hoạt động học tập','Nhóm giỏi đã vẽ xong biểu đồ khí hậu, trong khi nhóm khác vẫn chưa hiểu số liệu trục tung.',[$c('Giao nhiệm vụ mở rộng cho nhóm nhanh và cử đại diện hỗ trợ nhóm chậm theo gợi ý từng nấc',3,'Dạy học phân hóa (Differentiated Instruction) đỉnh cao! Tất cả học sinh đều được thử thách vừa sức.',['empathy'=>3,'decision'=>3,'creativity'=>2],0),$c('Bảo nhóm làm nhanh ngồi yên giữ trật tự chờ các bạn',1,'Lãng phí thời gian và triệt tiêu động lực học tập của những học sinh tiềm năng.',['decision'=>1],1),$c('Làm hộ nhóm chậm toàn bộ bài tập để kịp giờ giáo án',0,'Tước đoạt cơ hội tự khám phá và rèn luyện tư duy của học sinh.',['empathy'=>1],2)],'Công bằng sư phạm không phải là cho mọi người cùng một sự hỗ trợ như nhau.'),
        $m(2,'priority_order','Quy trình xử lý quan niệm sai lầm (Misconception)','Một học sinh đứng dậy cãi: \'Hôm nay trời rất lạnh, chứng tỏ Trái Đất đâu có nóng lên!\'.',[$c('1. Khen câu hỏi sắc sảo -> 2. Cho xem dữ liệu nhiệt độ 50 năm -> 3. Phân biệt Thời tiết (ngắn hạn) và Khí hậu (dài hạn)',3,'Nghệ thuật sư phạm bậc thầy! Biến một thắc mắc phản biện thành cơ hội vàng để khai sáng cho cả lớp.',['empathy'=>3,'analysis'=>3,'precision'=>2],0),$c('1. Nói em sai rồi -> 2. Yêu cầu chép phạt định nghĩa -> 3. Bắt ngồi xuống',0,'Làm tổn thương lòng tự trọng học sinh và dập tắt tinh thần dám nêu ý kiến phản biện.',['empathy'=>0],1),$c('1. Lờ đi như không nghe thấy -> 2. Tiếp tục nói bài của mình',0,'Bỏ qua lỗ hổng kiến thức quan trọng mà nhiều học sinh khác cũng có thể đang mắc phải.',['decision'=>0],2)],'Quy tắc sư phạm: Ghi nhận câu hỏi -> Dùng bằng chứng khoa học -> Phân biệt khái niệm.'),
        $m(3,'trade_off','Kiểm soát thời lượng giáo án','Học sinh thảo luận quá sôi nổi, thời gian còn lại không đủ để làm hết 3 bài tập sách giáo khoa.',[$c('Chốt lại các ý cốt lõi của phần tranh luận, chuyển 2 bài tập thành dự án nhỏ tự chọn về nhà (Ưu tiên: Chiều sâu nhận thức)',3,'Linh hoạt và bản lĩnh sư phạm! Bảo toàn năng lượng say mê của học sinh mà vẫn chốt được tri thức.',['decision'=>3,'creativity'=>2,'precision'=>2],0),$c('Cắt ngang phần thảo luận ngay lập tức và nói liên tục để kịp giờ (Ưu tiên: Hoàn thành hình thức)',1,'Đạt chỉ tiêu trang sách nhưng học sinh bị hụt hẫng và không kịp tiêu hóa kiến thức.',['precision'=>1],1),$c('Giữ học sinh lại thêm 15 phút giờ ra chơi để dạy cho hết bài',0,'Xâm phạm thời gian giải lao cần thiết để não bộ học sinh phục hồi năng lượng.',['empathy'=>0],2)],'Mục tiêu tối thượng của giáo dục là sự thấu hiểu sâu sắc, không phải là \'chạy hết giáo án\'.'),
        $m(3,'single_choice','Xử lý xung đột nhóm trong giờ học','Hai học sinh tranh cãi gay gắt xem ai là người phải lên bảng thuyết trình.',[$c('Đến bên nhóm, gợi ý chia đôi phần: một bạn trình bày ý tưởng, một bạn trả lời câu hỏi phản biện',3,'Giải quyết xung đột cùng thắng (Win-Win)! Giúp các em học cách cộng tác và sẻ chia trách nhiệm.',['empathy'=>3,'decision'=>3,'creativity'=>2],0),$c('Trừ điểm cả hai em vì gây mất trật tự lớp',1,'Trừng phạt mà chưa lắng nghe nguyên nhân khó khăn của học sinh.',['empathy'=>1],1),$c('Bắt em ít nói hơn phải lên bảng một mình',0,'Tạo thêm áp lực tâm lý cho học sinh rụt rè.',['empathy'=>0],2)],'Biến tình huống va chạm thành bài học kỹ năng làm việc nhóm thực thụ.'),
        $m(4,'single_choice','Đánh giá quá trình cuối giờ (Exit Ticket)','Còn 4 phút trước khi tiếng chuông tan tiết vang lên.',[$c('Phát phiếu thoát hiểm nhỏ: Ghi 1 điều em hiểu sâu nhất và 1 câu hỏi em vẫn còn băn khoăn',3,'Phương pháp đánh giá vì sự tiến bộ (Formative Assessment)! Lắng nghe nhịp đập tư duy của từng học sinh.',['analysis'=>3,'empathy'=>3,'precision'=>2],0),$c('Hỏi bâng quơ: \'Cả lớp hiểu hết chưa?\' rồi chào ra về',1,'Câu hỏi chung chung chỉ nhận lại sự im lặng thụ động của cả phòng học.',['empathy'=>1],1),$c('Bật máy chiếu dạy nhồi thêm một đoạn kiến thức mới tinh',0,'Nhồi nhét phút chót gây quá tải nhận thức và làm phân tán kiến thức vừa học.',['decision'=>0],2)],'Thu thập phản hồi ngắn cuối giờ giúp bạn điều chỉnh bài giảng ngày mai.'),
        $m(4,'trade_off','Nhận xét khích lệ học sinh yếu thế','Một học sinh thường xuyên đạt điểm thấp hôm nay đã dũng cảm xung phong phát biểu dù câu trả lời chưa trọn vẹn.',[$c('Ghi nhận sự tiến bộ và lòng dũng cảm trước cả lớp, chỉ ra điểm đúng trong ý tưởng của em (Ưu tiên: Nuôi dưỡng niềm tin)',3,'Tâm hồn người làm thầy vĩ đại! Bạn vừa gieo một hạt mầm tự tin quý giá vào tâm hồn học trò.',['empathy'=>3,'decision'=>2],0),$c('Chỉ thẳng vào chỗ sai và bảo em cần cố gắng nhiều hơn mới bằng các bạn (Ưu tiên: Thước đo học lực)',1,'Phê bình thiếu tinh tế sẽ làm học sinh co mình lại và không bao giờ dám giơ tay nữa.',['empathy'=>0],1),$c('Cho điểm 10 tròn trĩnh ngay lập tức dù bài làm sai nhiều (Ưu tiên: Động viên quá đà)',1,'Động viên tốt nhưng cho điểm không đúng thực tế sẽ tạo hiểu lầm về năng lực.',['precision'=>1],2)],'Một lời khen đúng lúc của thầy cô có thể thắp sáng tương lai của một đứa trẻ.')
    ],['title'=>'Nghệ thuật giải thích dễ hiểu (Feynman Technique)','duration'=>'15 phút','action'=>'Chọn một khái niệm khoa học bạn vừa học (ví dụ: Định luật bảo toàn năng lượng, Quang hợp, hoặc Thuật toán). Giải thích khái niệm đó cho một người em nhỏ hoặc người thân trong 3 phút bằng ví dụ đời sống mà không dùng thuật ngữ cao siêu.','reflection_question'=>'Khi người nghe gật gù hiểu ra điều bạn nói, bạn có cảm nhận được niềm hạnh phúc của người truyền cảm hứng không?']),
    'chuyen-vien-marketing' => $game('Ra mắt bình nước học đường','Chuyên viên Marketing','Một thương hiệu nhỏ sắp ra mắt bình nước tái sử dụng cho học sinh với ngân sách 20 triệu đồng.','Campaign Room · 7 ngày',[
        $m(1,'single_choice','Xác định chân dung khách hàng mục tiêu','Đội sản xuất hào hứng nói: \'Khách hàng của chúng ta là tất cả mọi người có uống nước!\'.',[$c('Phỏng vấn nhanh 15 học sinh, chia nhóm nhu cầu và chọn phân khúc trọng tâm là học sinh cấp 3 yêu thể thao',3,'Phân khúc sắc bén! Định vị rõ giúp thông điệp chạm đúng tim đen và tiết kiệm từng đồng ngân sách.',['analysis'=>3,'empathy'=>3,'decision'=>2],0),$c('Đồng ý nhắm đến toàn bộ từ người già đến trẻ nhỏ để không bỏ sót thị phần',1,'Thông điệp chung chung nhạt nhòa, ngân sách 20 triệu sẽ tan biến như muối bỏ biển.',['decision'=>0],1),$c('Chỉ lấy ý thích cá nhân của bản thân làm chuẩn mực duy nhất cho sản phẩm',1,'Thiên kiến cá nhân không thể thay thế nghiên cứu dữ liệu thị trường khách quan.',['analysis'=>1],2)],'Marketing nhắm đến tất cả mọi người là không chạm đến bất kỳ ai.'),
        $m(1,'trade_off','Khảo sát nỗi đau khách hàng (Pain Points)','Học sinh dùng bình nước thường gặp nhiều phiền toái trong cặp sách.',[$c('Tập trung giải quyết nỗi sợ rò rỉ nước làm ướt sách vở và khả năng giữ lạnh cả buổi học (Ưu tiên: Tính năng cốt lõi)',3,'Đánh trúng nỗi đau kinh điển của học sinh! Đây là lý do thuyết phục nhất để họ mua bình mới.',['empathy'=>3,'analysis'=>3],0),$c('Tập trung thiết kế thật nhiều sticker anime dán bên ngoài vỏ bình (Ưu tiên: Hình thức bề ngoài)',2,'Hút mắt ban đầu nhưng nếu bình bị rỉ nước, khách hàng sẽ lập tức bỏ rơi thương hiệu.',['creativity'=>3],1),$c('Làm bình dung tích cực lớn 3 lít cho học sinh đỡ phải lấy nước nhiều lần (Ưu tiên: Dung tích)',1,'Quá to nặng, không vừa ngăn cặp sách của học sinh.',['precision'=>1],2)],'Sản phẩm chiến thắng khi giải quyết triệt để một nỗi đau có thật của người dùng.'),
        $m(2,'single_choice','Kiểm thử thông điệp truyền thông (A/B Testing)','Đội sáng tạo đưa ra 3 phương án câu khẩu hiệu (Slogan) khác nhau.',[$c('Chạy thử 3 bài đăng nhỏ với ngân sách 500k để đo lường tỷ lệ tương tác và bấm mua thực tế',3,'Dựa trên dữ liệu (Data-driven)! Bạn để thị trường thật trả lời thay vì ngồi tranh cãi cảm tính.',['analysis'=>3,'precision'=>3,'decision'=>2],0),$c('Chọn câu slogan: \'Bình nước số 1 vũ trụ không đối thủ\' vì nghe rất kêu',0,'Quảng cáo phóng đại vô căn cứ làm giảm uy tín thương hiệu và vi phạm luật quảng cáo.',['decision'=>0],1),$c('Liệt kê toàn bộ 15 thông số kỹ thuật của bình vào một bức ảnh dày đặc chữ',1,'Quá nhiều thông tin kỹ thuật làm loãng điểm nhấn, khách hàng sẽ lướt qua trong 1 giây.',['creativity'=>1],2)],'Một chiến dịch thành công cần một lời hứa thương hiệu rõ ràng và kiểm chứng được.'),
        $m(2,'priority_order','Quy trình thiết kế phễu chuyển đổi (Marketing Funnel)','Bạn cần dẫn dắt một học sinh từ lúc chưa biết gì đến khi quyết định đặt mua bình.',[$c('1. Video ngắn thử nghiệm độ bền rơi không vỡ -> 2. Tặng mã giảm giá trải nghiệm -> 3. Form đặt hàng giao tận lớp',3,'Phễu chuyển đổi mẫu mực! Dẫn dắt tâm lý tự nhiên từ tò mò đến mua hàng thuận tiện.',['analysis'=>3,'creativity'=>3,'precision'=>2],0),$c('1. Gửi tin nhắn spam link mua hàng vào hộp thư học sinh -> 2. Ép mua -> 3. Không giải thích gì',0,'Spam gây ức chế và làm hỏng hoàn toàn hình ảnh thương hiệu trong mắt giới trẻ.',['empathy'=>0],1),$c('1. Chỉ làm video nghệ thuật trừu tượng -> 2. Không để lại bất kỳ đường link hay thông tin mua hàng nào',1,'Có người xem nhưng không ai biết mua ở đâu, chiến dịch thất bại về mặt kinh doanh.',['decision'=>1],2)],'Mô hình AIDA: Nhận biết (Awareness) -> Hứng thú (Interest) -> Khao khát (Desire) -> Hành động (Action).'),
        $m(3,'trade_off','Phân bổ ngân sách chiến dịch 20 triệu','Bạn có các kênh: Influencer học đường (KOL), quầy trải nghiệm tại trường (Event) và Quảng cáo số (Ads).',[$c('Dành 10 triệu cho gian hàng thử thách rơi tự do tại sân trường, 7 triệu Ads số, giữ 3 triệu tối ưu (Ưu tiên: Trải nghiệm thực tế)',3,'Sự kết hợp hoàn hảo giữa tương tác trực tiếp (O2O) và khuếch đại trực tuyến!',['decision'=>3,'analysis'=>3,'creativity'=>2],0),$c('Dồn hết 20 triệu thuê 1 bạn TikToker nổi tiếng quay 1 video 15 giây (Ưu tiên: Canh bạc một lần)',1,'Rủi ro tập trung quá lớn, nếu video không lên xu hướng bạn sẽ trắng tay.',['decision'=>1],1),$c('Chia đều mỗi kênh một ít mà không có trọng tâm rõ ràng',1,'Ngân sách bị phân tán manh mún, không tạo ra được cú hích nào đáng kể.',['precision'=>1],2)],'Phân bổ ngân sách thông minh: Dành phần lớn cho kênh hiệu quả và giữ lại quỹ tối ưu linh hoạt.'),
        $m(3,'single_choice','Xử lý khi video triệu view nhưng không ai mua hàng','Clip hài hước về chiếc bình đạt 500.000 lượt xem trên TikTok nhưng chỉ có 2 đơn đặt hàng.',[$c('Rà soát lại đường dẫn bio, thông điệp kêu gọi hành động (CTA) và tạo ưu đãi giới hạn 48 giờ',3,'Tư duy tối ưu tỷ lệ chuyển đổi (CRO) chuẩn mực! Bạn chuyển hóa độ chú ý thành doanh thu thực tế.',['analysis'=>3,'decision'=>3,'creativity'=>2],0),$c('Bỏ thêm 10 triệu đi mua lượt xem ảo để báo cáo trông đẹp mắt hơn',0,'Lừa dối số liệu không giải quyết được bài toán dòng tiền của doanh nghiệp.',['precision'=>0],1),$c('Đóng cửa dự án ngay lập tức vì kết luận sản phẩm này vô dụng',1,'Bỏ cuộc quá vội vàng khi chưa thử nghiệm tối ưu các điểm nghẽn của luồng mua.',['analysis'=>1],2)],'Phân biệt chỉ số phù phiếm (Vanity Metrics) và chỉ số kinh doanh cốt lõi (Conversion Rate).'),
        $m(4,'single_choice','Đạo đức quảng cáo xanh (Chống Greenwashing)','Đội thiết kế muốn in dòng chữ \'Bình nước 100% tự phân hủy sinh học bảo vệ đại dương\' dù chất liệu là nhựa PP tái chế.',[$c('Kiên quyết từ chối ghi sai sự thật; truyền thông đúng: \'Nhựa tái chế an toàn, giảm thiểu rác thải nhựa một lần\'',3,'Bản lĩnh của người làm truyền thông chân chính! Bảo vệ thương hiệu khỏi khủng hoảng tẩy chay tẩy xanh.',['precision'=>3,'empathy'=>3,'decision'=>3],0),$c('Đồng ý in dòng chữ tự phân hủy để bán được thật nhiều hàng trước mắt',0,'Hành vi lừa dối người tiêu dùng, vi phạm nghiêm trọng đạo đức kinh doanh.',['precision'=>0],1),$c('Không ghi bất kỳ thông tin chất liệu nào lên nhãn mác',1,'Thiếu minh bạch, khiến khách hàng nghi ngờ chất lượng an toàn vệ sinh của bình.',['analysis'=>1],2)],'Sự trung thực và minh bạch là tài sản vô giá duy nhất giữ chân khách hàng lâu dài.'),
        $m(4,'trade_off','Lắng nghe phản hồi tiêu cực của khách hàng','Một học sinh đăng bài phàn nàn trên trang cá nhân rằng nắp bình bị lỏng sau 3 ngày dùng.',[$c('Chủ động bình luận công khai xin lỗi, gửi đổi bình mới ngay tận tay và thu hồi bình lỗi để kiểm tra kỹ thuật (Ưu tiên: Trách nhiệm & Dịch vụ khách hàng)',3,'Xử lý khủng hoảng truyền thông 10/10! Biến một sự cố thành minh chứng cho sự tận tâm của thương hiệu.',['empathy'=>3,'decision'=>3,'precision'=>2],0),$c('Nhắn tin riêng yêu cầu bạn học sinh xóa bài ngay nếu không sẽ kiện (Ưu tiên: Đe dọa)',0,'Thái độ hung hăng sẽ thổi bùng ngọn lửa tẩy chay của cả cộng đồng học sinh.',['empathy'=>0],1),$c('Chặn tài khoản của khách hàng và xóa các bình luận tiêu cực (Ưu tiên: Bịt miệng dư luận)',0,'Hành động thiếu văn minh làm mất sạch niềm tin của công chúng.',['decision'=>0],2)],'Khách hàng phàn nàn là cơ hội tốt nhất để biến người thất vọng thành fan trung thành.')
    ],['title'=>'Viết 3 góc nhìn thông điệp quảng cáo (Copywriting)','duration'=>'15 phút','action'=>'Chọn một vật phẩm quen thuộc trên bàn học (bút bi, cuốn sổ, hoặc tai nghe). Viết 3 dòng quảng cáo ngắn (dưới 20 từ/dòng): 1 câu hài hước đánh vào Gen Z, 1 câu nêu thông số kỹ thuật, và 1 câu đánh thức cảm xúc bảo vệ môi trường.','reflection_question'=>'Bạn thấy cách tiếp cận nào dễ khiến bạn bè xung quanh muốn mở ví mua hàng nhất?']),
    'kien-truc-su' => $game('Thiết kế thư viện sân trường','Kiến trúc sư dự án','Nhà trường muốn biến góc sân 60m² thành thư viện mở, mát mẻ, an toàn và dễ tiếp cận cho mọi học sinh.','Design Charrette · 1 tuần',[
        $m(1,'single_choice','Khảo sát hiện trạng khu đất','Khu đất 60m² hướng chính Tây, có một cây bàng cổ thụ tỏa bóng mát ở góc.',[$c('Đo hướng nắng, hướng gió mùa, luồng đi lại của học sinh và giữ cây bàng làm tâm điểm che nắng',3,'Tư duy kiến trúc sinh khí hậu chuẩn mực! Bạn tận dụng bóng mát tự nhiên để giảm nhiệt cho công trình.',['analysis'=>3,'precision'=>3,'creativity'=>2],0),$c('Đề xuất chặt bỏ cây bàng để mặt bằng vuông vức dễ chia ô xây dựng',0,'Phá hủy tài sản sinh thái quý giá và làm công trình bị nung nóng gay gắt dưới nắng Tây.',['empathy'=>0],1),$c('Ngồi vẽ concept 3D hoành tráng trước mà không cần ra đo đạc thực tế',1,'Bản vẽ có thể đẹp mắt nhưng khi ra thi công sẽ xung đột nghiêm trọng với hiện trạng.',['creativity'=>1],2)],'Hiện trạng tự nhiên không phải là trở ngại, mà là người bạn đồng hành của kiến trúc sư.'),
        $m(1,'trade_off','Dung hòa nhu cầu các nhóm người dùng','Học sinh muốn có góc nằm đọc sách thoải mái; giáo viên muốn tầm nhìn mở dễ bao quát; thủ thư muốn chống mưa hắt bảo vệ sách.',[$c('Bố trí bậc ngồi đa tầng (amphitheater) nhìn ra vườn, dùng vách kính trượt linh hoạt (Ưu tiên: Không gian đa năng)',3,'Giải pháp không gian tuyệt hảo! Vừa tạo tư thế ngồi thư giãn, vừa bao quát tốt và chống mưa nắng hiệu quả.',['creativity'=>3,'empathy'=>3,'analysis'=>2],0),$c('Kê các dãy bàn ghế gỗ thẳng tắp như phòng thi đại học (Ưu tiên: Dễ quản lý trật tự)',1,'Rất dễ quản lý nhưng làm mất đi hoàn toàn tinh thần của một \'thư viện mở\' thân thiện.',['precision'=>1],1),$c('Xây thành các phòng nhỏ khép kín hoàn toàn (Ưu tiên: Chống ồn và bảo vệ sách)',1,'Bảo vệ sách tốt nhưng gây cảm giác bí bách ngột ngạt và khó quan sát an toàn.',['decision'=>1],2)],'Thiết kế giỏi không chọn bên thắng mà biến xung đột thành cấu trúc không gian thông minh.'),
        $m(2,'single_choice','Tổ chức dây chuyền công năng và ánh sáng','Ánh sáng tự nhiên rất cần cho việc đọc sách nhưng ánh nắng trực tiếp sẽ làm hỏng giấy và lóa mắt.',[$c('Bố trí lam chắn nắng bằng gỗ hướng Tây, mở cửa đón ánh sáng dịu hướng Bắc và trên mái',3,'Xử lý vi khí hậu bậc thầy! Không gian tràn ngập ánh sáng tự nhiên êm dịu, không cần bật đèn ban ngày.',['precision'=>3,'analysis'=>3,'creativity'=>2],0),$c('Bịt kín toàn bộ tường bằng bê tông và lắp 20 bóng đèn huỳnh quang',1,'Giải quyết được vấn đề lóa mắt nhưng tiêu tốn điện năng và mất kết nối với thiên nhiên.',['analysis'=>1],1),$c('Lắp toàn bộ kính trong suốt cả 4 mặt mà không có mái đua che nắng',0,'Tạo ra hiệu ứng nhà kính khổng lồ biến thư viện thành một lò thiêu ngột ngạt.',['decision'=>0],2)],'Lấy sáng gián tiếp từ hướng Bắc hoặc tán xạ qua lam chắn là bí quyết của kiến trúc xanh.'),
        $m(2,'priority_order','Quy trình thiết kế hồ sơ kỹ thuật thi công','Bạn cần chuẩn bị bộ hồ sơ để đội thợ bắt đầu xây dựng.',[$c('1. Thiết kế ý tưởng concept -> 2. Bản vẽ mặt bằng, mặt cắt chi tiết -> 3. Bóc tách khối lượng và chỉ định vật liệu',3,'Đúng quy trình hành nghề kiến trúc sư! Đảm bảo công trình thi công chuẩn xác từng milimet.',['precision'=>3,'analysis'=>3],0),$c('1. Mua vật liệu về để sẵn -> 2. Thợ tự xây đến đâu vẽ đến đó -> 3. Không cần dự toán',0,'Xây dựng tùy tiện dẫn đến lãng phí, mất an toàn kết cấu và vỡ ngân sách.',['decision'=>0],1),$c('1. Chỉ vẽ phối cảnh 3D lung linh -> 2. Bỏ qua bản vẽ mặt cắt kỹ thuật',1,'Thợ không thể thi công được nếu thiếu các thông số kích thước cấu kiện thực tế.',['precision'=>1],2)],'Quy trình chuẩn: Phác thảo ý tưởng -> Mặt bằng kỹ thuật -> Lựa chọn vật liệu & Dự toán.'),
        $m(3,'trade_off','Kiểm soát ngân sách khi vật liệu đội giá','Chi phí thực tế vượt 20% ngân sách cho phép do giá thép và kính cường lực tăng cao.',[$c('Thay một phần khung thép bằng kết cấu gạch mộc và tre địa phương, giữ nguyên công năng cốt lõi (Ưu tiên: Bản sắc & Ngân sách)',3,'Quyết định tài tình! Vừa tiết kiệm chi phí, vừa tạo điểm nhấn kiến trúc mộc mạc độc đáo.',['creativity'=>3,'analysis'=>3,'decision'=>2],0),$c('Cắt bỏ toàn bộ hệ thống mái che mưa nắng (Ưu tiên: Cắt giảm thô)',0,'Đạt ngân sách nhưng biến công trình thành vô dụng khi trời mưa hay nắng gắt.',['decision'=>0],1),$c('Giữ nguyên thiết kế đắt đỏ và ép nhà trường phải tự đi vay tiền bù vào',1,'Thiếu tôn trọng ràng buộc tài chính của chủ đầu tư, dự án có nguy cơ bị hủy bỏ.',['empathy'=>0],2)],'Kiến trúc sư giỏi biết tối ưu giá trị (Value Engineering) thay vì chỉ cắt xén cơ học.'),
        $m(3,'single_choice','Thiết kế tiếp cận phổ quát (Universal Design)','Bạn phát hiện lối vào bục đọc sách chính cao hơn mặt sân 60cm và chỉ có bậc thang.',[$c('Thiết kế thêm ram dốc thoải với độ dốc chuẩn 1/12 và tay vịn an toàn cho học sinh đi xe lăn',3,'Nhân văn và chuẩn mực thiết kế công cộng! Thư viện thực sự chào đón tất cả mọi thành viên.',['empathy'=>3,'precision'=>3,'decision'=>2],0),$c('Để nguyên bậc thang và làm biển báo: \'Học sinh xe lăn vui lòng ngồi đọc ở góc phụ dưới sân\'',0,'Tạo ra sự phân biệt đối xử và trải nghiệm cô lập đáng buồn cho học sinh khuyết tật.',['empathy'=>0],1),$c('Bảo khi nào có bạn đi xe lăn thì nhờ các bạn khác khiêng cả người và xe lên',1,'Vô cùng nguy hiểm, tiềm ẩn nguy cơ ngã chấn thương và làm mất sự tự chủ của em.',['decision'=>1],2)],'Kiến trúc bao trùm đảm bảo người dùng xe lăn hoặc chống nạng đều tiếp cận bình đẳng.'),
        $m(4,'single_choice','Giám sát tác giả tại công trường','Đội thợ tự ý thay loại sơn chống thấm ngoài trời bằng sơn nội thất rẻ tiền để ăn bớt tiền công.',[$c('Lập biên bản đình chỉ hạng mục sơn, yêu cầu cạo bỏ và sơn lại đúng chủng loại chống thấm đã cam kết',3,'Cương trực và kiên quyết! Bạn bảo vệ công trình khỏi bị ẩm mốc rêu phong sau mùa mưa đầu tiên.',['precision'=>3,'decision'=>3,'empathy'=>1],0),$c('Tặc lưỡi bỏ qua vì nghĩ sơn nào nhìn bên ngoài cũng giống nhau',0,'Thỏa hiệp với gian lận kỹ thuật sẽ làm công trình xuống cấp chỉ sau vài tháng.',['precision'=>0],1),$c('Nhận tiền phong bì của thợ để làm ngơ cho qua',0,'Vi phạm nghiêm trọng pháp luật xây dựng và đạo đức nghề nghiệp.',['decision'=>0],2)],'Bảo vệ chất lượng công trình đến viên gạch cuối cùng là trách nhiệm danh dự của KTS.'),
        $m(4,'trade_off','Bàn giao và hướng dẫn vận hành bền vững','Công trình hoàn thành đẹp đẽ, sẵn sàng mở cửa cho học sinh đón nhận.',[$c('Cùng câu lạc bộ học sinh trồng cây quanh thư viện và hướng dẫn mở cửa đón gió tự nhiên (Ưu tiên: Gắn kết cộng đồng)',3,'Tuyệt vời! Bạn trao quyền cho học sinh trở thành những người chủ gìn giữ không gian này.',['empathy'=>3,'creativity'=>3,'decision'=>2],0),$c('Bàn giao chìa khóa cho bảo vệ rồi lập tức rời đi (Ưu tiên: Hết việc hợp đồng)',1,'Xong thủ tục nhưng thiếu đi sự kết nối và hướng dẫn vận hành tối ưu cho người dùng.',['precision'=>1],1),$c('Cấm học sinh chạm vào các mảng tường gỗ vì sợ bị xước (Ưu tiên: Giữ công trình nguyên vẹn)',0,'Biến thư viện thành bảo tàng vô cảm thay vì một không gian học tập sống động.',['empathy'=>0],2)],'Công trình kiến trúc chỉ thực sự sống khi cộng đồng biết cách yêu thương và sử dụng nó.')
    ],['title'=>'Vẽ mặt bằng công năng góc học tập (Floor Plan)','duration'=>'15 phút','action'=>'Dùng thước dây hoặc bước chân đo góc học tập của bạn. Vẽ một bản phác thảo mặt bằng nhìn từ trên xuống (tỷ lệ 1 ô ly vở = 20cm). Đánh dấu vị trí bàn, ghế, cửa sổ, hướng gió và hướng ánh sáng mặt trời chiếu vào.','reflection_question'=>'Khi nhìn không gian dưới dạng mặt bằng hình học, bạn có phát hiện ra góc nào đang bị lãng phí diện tích không?']),
    'ky-su-co-khi' => $game('Khôi phục băng tải mini','Kỹ sư cơ khí','Băng tải phân loại mô hình bị rung mạnh và phát ra tiếng ồn lạ trước buổi trình diễn. Bạn cần tìm lỗi mà vẫn bảo đảm an toàn.','Xưởng cơ khí · 14:10',[
        $m(1,'single_choice','Tiếp cận hiện trường an toàn (Safety First)','Băng tải vẫn đang cắm điện chạy và phát ra tiếng va đập kim loại lọc cọc dữ dội.',[$c('Nhấn nút dừng khẩn cấp (E-Stop), ngắt cầu dao điện, gắn thẻ khóa cảnh báo (LOTO) trước khi kiểm tra',3,'Thao tác vàng của kỹ sư cơ khí chuyên nghiệp! Tuyệt đối không bao giờ chẩn đoán khi máy đang chạy.',['precision'=>3,'decision'=>3],0),$c('Cúi sát mặt vào các bánh răng đang quay tít để nghe ngóng xem tiếng kêu ở đâu',0,'Cực kỳ nguy hiểm! Bộ phận chuyển động có thể cuốn tóc, quần áo và gây thương tật nặng.',['decision'=>0],1),$c('Tăng tốc độ động cơ lên mức cực đại xem máy có tự hết kêu không',0,'Tăng tải trên một hệ thống đang hỏng hóc có thể làm vỡ ổ bi và bắn mảnh kim loại ra ngoài.',['analysis'=>0],2)],'Trong kỹ thuật cơ khí, an toàn tính mạng luôn đi trước áp lực tiến độ.'),
        $m(1,'trade_off','Quan sát dấu vết cơ học ban đầu','Máy đã dừng hẳn và an toàn. Bạn cần khoanh vùng các bộ phận nghi vấn.',[$c('Dùng đèn pin soi kỹ bụi mạt cao su đen dưới gầm puly và vết bóng bất thường trên thành kim loại (Ưu tiên: Thu thập manh mối vật lý)',3,'Kỹ năng khám nghiệm cơ khí tuyệt vời! Bụi cao su chứng tỏ dây đai đang bị ma sát trượt lệch tâm.',['analysis'=>3,'precision'=>3],0),$c('Dùng tay quay thử trục và lắc nhẹ từng khớp nối để cảm nhận độ rơ lỏng (Ưu tiên: Cảm giác xúc giác)',2,'Phương pháp tốt để cảm nhận độ rơ của ổ bi và khớp nối.',['analysis'=>2,'precision'=>2],1),$c('Đoán mò là do hỏng động cơ điện mà không buồn kiểm tra các chi tiết truyền động',1,'Kết luận vội vàng khi chưa kiểm tra cơ cấu truyền động trung gian.',['decision'=>1],2)],'Mỗi vết xước, mạt sắt hay bụi cao su đều là bằng chứng chỉ điểm lỗi cơ khí.'),
        $m(2,'single_choice','Tìm nguyên nhân gốc rễ bằng đo kiểm','Dây đai truyền động bị lệch hẳn về một bên mép puly.',[$c('Dùng thước đo độ đồng phẳng giữa 2 trục puly và kiểm tra độ căng của dây đai',3,'Chẩn đoán chính xác! Hai trục không song song là nguyên nhân số một làm dây đai bị leo mép.',['analysis'=>3,'precision'=>3],0),$c('Dùng tay cố sức đẩy dây đai về chính giữa rồi bật máy chạy tiếp',1,'Chỉ xử lý phần ngọn tạm thời, bật máy lên dây đai sẽ lập tức bị kéo lệch lại.',['decision'=>1],1),$c('Bôi thật nhiều dầu nhớt lên bề mặt dây đai cao su',0,'Dầu nhớt làm trơn trượt và phân hủy cao su khiến dây đai trượt hoàn toàn.',['precision'=>0],2)],'Đo đạc chính xác bằng dụng cụ giúp phân biệt nguyên nhân gốc rễ với triệu chứng bề mặt.'),
        $m(2,'priority_order','Quy trình căn chỉnh và siết bu-lông gá động cơ','Phát hiện bu-lông chân đế puly bị lỏng do thiếu vòng đệm vênh (lock washer).',[$c('1. Lắp vòng đệm vênh hãm -> 2. Dùng cờ-lê cân lực (Torque wrench) siết đúng mô-men quy định -> 3. Đánh vạch sơn kiểm tra (Torque stripe)',3,'Quy chuẩn cơ khí chính xác hàng không! Vạch sơn giúp kiểm tra bằng mắt thường xem bu-lông có bị tự tháo không.',['precision'=>3,'analysis'=>2,'decision'=>2],0),$c('1. Nối thêm ống tuýp dài 1 mét vào cờ-lê siết hết sức bình sinh -> 2. Không cần vòng đệm',1,'Quá lực siết làm cháy ren ốc hoặc làm nứt tai gá kim loại của máy.',['decision'=>1],1),$c('1. Nhét mẩu giấy vào khe ren -> 2. Siết lỏng tay cho êm',0,'Biện pháp nguy hiểm có thể làm cụm truyền động văng ra khi máy hoạt động.',['precision'=>0],2)],'Quy tắc lắp ráp: Đúng phụ kiện chống tháo -> Căn lực siết theo chuẩn -> Đánh dấu vị trí.'),
        $m(3,'single_choice','Đánh giá và thay thế vòng bi (Bearing)','Sau khi căn chỉnh dây đai, quay tay trục vẫn thấy cảm giác lạo xạo cấn ngón tay.',[$c('Dùng cảo chuyên dụng tháo vòng bi cũ ra, vệ sinh gối đỡ và ép vòng bi mới cùng mã số kỹ thuật',3,'Kỹ thuật thay thế chuẩn xác! Bảo vệ trục không bị biến dạng và phục hồi độ êm ái 100%.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('Lấy búa sắt đập thật mạnh trực tiếp vào vòng bi để tống nó ra ngoài',0,'Búa đập trực tiếp làm cong vênh trục máy và hỏng luôn vỏ gối đỡ đắt tiền.',['precision'=>0],1),$c('Chỉ bơm thêm mỡ bò vào vòng bi vỡ rồi dùng tiếp',1,'Giải pháp tạm bợ, các mạt thép vỡ sẽ tiếp tục nghiền nát ngõng trục động cơ.',['decision'=>1],2)],'Một vòng bi đã mòn rãnh lăn không bao giờ có thể hồi phục bằng việc bôi thêm mỡ.'),
        $m(3,'trade_off','Đánh đổi giữa vật liệu kim loại và nhựa kỹ thuật','Cần thay một bánh răng dẫn hướng: bánh răng thép rất bền nhưng kêu to; bánh răng nhựa POM êm nhẹ nhưng chịu tải kém hơn.',[$c('Chọn bánh răng nhựa kỹ thuật POM cho mô hình trường học vì tải trọng nhẹ và ưu tiên giảm tiếng ồn (Ưu tiên: Độ êm ái & An toàn)',3,'Lựa chọn vật liệu thực tế và thông minh! Rất phù hợp với môi trường trình diễn giáo dục trong nhà.',['analysis'=>3,'decision'=>3],0),$c('Bắt buộc tiện bánh răng thép hợp kim tôi cứng đắt tiền (Ưu tiên: Độ bền tối đa)',2,'Rất bền nhưng nặng nề, tốn kém chi phí gia công và phát ra tiếng ồn kim loại lớn.',['precision'=>2],1),$c('Lấy miếng gỗ tự đẽo bánh răng lắp vào chạy thử',0,'Gỗ không đủ độ bền và kích thước modul bánh răng, sẽ bị gãy răng ngay khi khởi động.',['precision'=>0],2)],'Mỗi giải pháp vật liệu đều là bài toán tối ưu giữa độ bền, tiếng ồn và chi phí.'),
        $m(4,'single_choice','Quy trình chạy thử tải tăng dần (Commissioning)','Đã hoàn thành sửa chữa, thời gian chuẩn bị trình diễn còn 20 phút.',[$c('Chạy thử không tải 5 phút để đo nhiệt độ và độ rung, sau đó cho tải tăng dần 25%, 50% đến 100%',3,'Quy trình kiểm định hoàn hảo! Đảm bảo máy vận hành ổn định và phát hiện sớm bất thường nếu có.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('Chất đầy hàng hóa lên tối đa rồi bấm nút chạy hết tốc độ ngay lập tức',1,'Dễ gây sốc tải đột ngột làm đứt dây đai mới thay nếu có sai sót nhỏ.',['decision'=>1],1),$c('Bàn giao ngay mà không cần chạy thử vì tự tin tay nghề mình giỏi',0,'Tự mãn trong kỹ thuật là khởi đầu cho mọi tai nạn hỏng hóc đáng tiếc.',['precision'=>0],2)],'Kiểm chứng sửa chữa bằng tải trọng tăng dần từ từ, không bao giờ chạy full tải đột ngột.'),
        $m(4,'trade_off','Xây dựng quy trình bảo trì dự đoán (PdM)','Hệ thống hoạt động trơn tru trở lại trước sự thán phục của thầy cô.',[$c('Lập bảng checklist kiểm tra độ căng dây đai và tra dầu mỡ định kỳ hàng tháng (Ưu tiên: Bảo trì phòng ngừa lâu dài)',3,'Tư duy kỹ sư quản lý tài sản cơ điện! Ngăn chặn sự cố từ trong trứng nước.',['analysis'=>3,'precision'=>3,'decision'=>2],0),$c('Đóng hòm đồ nghề đi về và dặn: \'Khi nào hỏng lại thì gọi em\' (Ưu tiên: Chữa cháy bị động)',1,'Lối tư duy sửa chữa thụ động khiến máy móc luôn hoạt động trong tình trạng bất an.',['decision'=>1],1),$c('Đề xuất vứt bỏ toàn bộ băng tải sau mỗi lần trình diễn để mua mới',0,'Lãng phí ngân sách trường học một cách vô lý.',['analysis'=>0],2)],'Kỹ sư cơ khí giỏi không chỉ đi sửa máy hỏng, mà thiết lập hệ thống để máy không bao giờ hỏng.')
    ],['title'=>'Giải mã cơ cấu truyền động quanh bạn','duration'=>'15 phút','action'=>'Tìm một thiết bị cơ khí quen thuộc (xích xe đạp, bấm móng tay, hoặc quạt máy). Xác định xem chuyển động được truyền đi bằng cơ cấu nào (bánh răng, đòn bẩy, trục vít hay dây đai) và bôi trơn đóng vai trò gì.','reflection_question'=>'Cảm giác thấu hiểu cách máy móc biến lực nhỏ thành lực lớn có làm bạn say mê thế giới vật lý không?']),
    'chuyen-vien-tam-ly' => $game('Cuộc trò chuyện an toàn','Chuyên viên tham vấn học đường','Một học sinh xin gặp vì gần đây mất động lực học tập, hay lo âu và né tránh bạn bè. Mục tiêu là lắng nghe, đánh giá nhu cầu và giữ ranh giới nghề nghiệp.','Phòng tham vấn · 30 phút',[
        $m(1,'single_choice','Thiết lập không gian an toàn ban đầu','Học sinh bước vào phòng tham vấn, ngồi co ro ở mép ghế và nói: \'Em không biết bắt đầu từ đâu cả...\'.',[$c('Nhẹ nhàng giới thiệu nguyên tắc bảo mật và mời em chia sẻ theo bất cứ nhịp điệu nào em thấy thoải mái',3,'Mở đầu tham vấn mẫu mực! Giúp học sinh cảm thấy được đón nhận, xóa bỏ sự đề phòng và xây dựng niềm tin.',['empathy'=>3,'precision'=>2,'decision'=>2],0),$c('Hỏi dồn dập 5 câu liên tiếp về điểm số và quan hệ gia đình để lấy dữ liệu nhanh',1,'Biến phòng tham vấn thành phòng hỏi cung khiến học sinh càng thêm đóng chặt lòng mình.',['analysis'=>1],1),$c('Kể liên tục chuyện buồn của bản thân mình để chứng minh mình cũng từng khổ như em',1,'Thiện ý nhưng cướp mất tâm điểm của buổi tham vấn khỏi thân chủ.',['empathy'=>1],2)],'Cảm giác an toàn và sự tôn trọng quyền tự chủ là nền móng đầu tiên của tham vấn tâm lý.'),
        $m(1,'trade_off','Quan sát ngôn ngữ cơ thể (Non-verbal cues)','Em nói \'Em bình thường\' nhưng hai bàn tay siết chặt vặn vẹo vào gấu áo và mắt nhìn xuống sàn.',[$c('Nhẹ nhàng phản ánh quan sát: \'Thầy/Cô nhận thấy em đang siết chặt tay, dường như có điều gì đang làm em thấy căng thẳng?\' (Ưu tiên: Phản ánh tinh tế)',3,'Kỹ thuật phản ánh tinh nhạy! Giúp học sinh nhận biết cảm xúc trên cơ thể mình một cách an toàn.',['empathy'=>3,'analysis'=>3],0),$c('Chỉ ghi chép vào sổ tay im lặng mà không phản hồi gì (Ưu tiên: Thu thập dữ liệu khách quan)',2,'Khách quan nhưng tạo khoảng cách lạnh lùng khiến học sinh thấy mình như vật thí nghiệm.',['precision'=>2],1),$c('Nói thẳng: \'Em nói dối, tay em run thế kia sao bảo bình thường!\' (Ưu tiên: Bóc trần sự thật)',0,'Gây sốc tâm lý và phá hủy hoàn toàn cảm giác an toàn vừa chớm nở.',['empathy'=>0],2)],'Ngôn ngữ không lời thường phản ánh chân thực cảm xúc sâu kín hơn câu từ bằng lời nói.'),
        $m(2,'single_choice','Lắng nghe thấu cảm và xác nhận cảm xúc','Em khóc và kể: \'Gần đây điểm thi của em tụt dốc, em thấy mình vô dụng và làm bố mẹ thất vọng...\'.',[$c('Lắng nghe chăm chú, đưa khăn giấy và nói: \'Cảm giác gánh trên vai kỳ vọng của bố mẹ quả thực rất nặng nề với em...\'',3,'Xác nhận cảm xúc (Validation) tuyệt hảo! Em cảm thấy nỗi đau của mình được công nhận và thấu hiểu.',['empathy'=>3,'analysis'=>2,'decision'=>2],0),$c('Trấn an ngay: \'Có gì đâu mà buồn, ai trong đời chẳng có lúc điểm kém!\'',1,'Có ý tốt nhưng vô tình phủ nhận và xem nhẹ cảm xúc chân thật của học sinh.',['empathy'=>1],1),$c('Rút ngay một bảng thời khóa biểu ra bảo em về học thêm 4 tiếng mỗi tối',0,'Đưa giải pháp hành động khi cảm xúc chưa được giải tỏa chỉ làm tăng thêm áp lực.',['decision'=>0],2)],'Thấu cảm là đứng cùng góc nhìn với thân chủ, không phải là phán xét hay khuyên bảo vội vã.'),
        $m(2,'priority_order','Quy trình phân tích suy nghĩ tự động tiêu cực (CBT)','Học sinh mang niềm tin tuyệt đối hóa: \'Nếu em không đỗ trường chuyên, đời em coi như vứt đi\'.',[$c('1. Nhận diện bẫy tư duy \'tất cả hoặc không có gì\' -> 2. Cùng tìm bằng chứng thực tế -> 3. Xây dựng góc nhìn cân bằng hơn',3,'Ứng dụng liệu pháp nhận thức hành vi (CBT) xuất sắc! Giúp học sinh tự tháo gỡ gọng kìm tư duy tiêu cực.',['analysis'=>3,'precision'=>3,'empathy'=>2],0),$c('1. Mắng em suy nghĩ nông cạn -> 2. Bắt em phải lạc quan ngay -> 3. Không giải thích gì thêm',0,'Phê phán làm học sinh càng tự ti và cảm thấy mình có lỗi vì đã buồn phiền.',['empathy'=>0],1),$c('1. Đồng ý rằng không đỗ chuyên là đời hỏng thật -> 2. Khuyên em từ bỏ ước mơ',0,'Cổ xúy cho tư duy bi kịch hóa, đẩy học sinh vào vòng xoáy tuyệt vọng.',['decision'=>0],2)],'Liệu pháp nhận thức hành vi: Nhận diện suy nghĩ -> Tìm bằng chứng phản bác -> Tái cấu trúc nhận thức.'),
        $m(3,'single_choice','Đánh giá an toàn và nguy cơ tự hại (Crisis Assessment)','Em cúi gầm mặt và thì thầm: \'Đôi lúc em chỉ muốn biến mất mãi mãi khỏi thế giới này...\'.',[$c('Bình tĩnh hỏi trực tiếp: \'Khi nghĩ muốn biến mất, em có từng nghĩ đến việc tự làm đau bản thân hay có kế hoạch cụ thể nào chưa?\'',3,'Kỹ năng can thiệp khủng hoảng chuẩn quốc tế! Hỏi trực tiếp không làm tăng nguy cơ, mà là bước bảo vệ sinh mạng.',['decision'=>3,'precision'=>3,'empathy'=>3],0),$c('Né tránh câu hỏi vì sợ nhắc đến chuyện chết chóc sẽ xui xẻo hoặc làm em nghĩ quẩn thêm',0,'Sai lầm nguy hiểm có thể bỏ lỡ cơ hội ngăn chặn một thảm kịch tự hại.',['decision'=>0],1),$c('Hứa sẽ giấu kín 100% mọi điều em nói kể cả khi em có ý định tự tử',0,'Vi phạm nguyên tắc phá vỡ bảo mật khi tính mạng thân chủ bị đe dọa.',['precision'=>0],2)],'Khi xuất hiện dấu hiệu nguy cơ tự làm hại, chuyên viên bắt buộc phải đánh giá trực tiếp và rõ ràng.'),
        $m(3,'trade_off','Cùng lập kế hoạch an toàn (Safety Plan)','Em xác nhận không có ý định tự tử, chỉ quá kiệt sức và cần một chỗ dựa tinh thần.',[$c('Cùng em chọn ra 2 người bạn/người thân đáng tin cậy nhất để gọi khi thấy quá tải, và đặt lịch gặp lại sau 3 ngày (Ưu tiên: Trao quyền & Mạng lưới hỗ trợ)',3,'Xây dựng kế hoạch an toàn (Safety Plan) mẫu mực! Em cảm thấy mình có người đồng hành và có lối thoát.',['empathy'=>3,'decision'=>3,'precision'=>2],0),$c('Tự ý gọi điện cho cả lớp trưởng và ban cán sự đến họp bàn giúp đỡ (Ưu tiên: Huy động tập thể)',0,'Biến chuyện riêng tư thành chủ đề bàn tán của tập thể làm em xấu hổ tột cùng.',['empathy'=>0],1),$c('Kết thúc buổi gặp và chúc em vui vẻ vì thấy hôm nay em đã nín khóc',1,'Sự nín khóc tạm thời không thay thế được việc theo dõi và hỗ trợ lâu dài.',['precision'=>1],2)],'Kế hoạch hỗ trợ thành công nhất là kế hoạch do chính thân chủ cùng tham gia kiến tạo.'),
        $m(4,'single_choice','Nguyên tắc bảo mật và ranh giới với phụ huynh','Tối đó phụ huynh gọi điện gắt gỏng đòi bạn phải kể lại từng câu từng chữ con họ đã nói trong phòng tham vấn.',[$c('Lịch sự giải thích quy tắc bảo mật của nghề, chỉ chia sẻ định hướng chung về cảm xúc và hướng dẫn bố mẹ cách lắng nghe con',3,'Bản lĩnh nghề nghiệp xuất sắc! Bạn vừa bảo vệ bí mật của học sinh vừa giúp bố mẹ trở thành đồng minh tốt hơn.',['precision'=>3,'empathy'=>3,'decision'=>3],0),$c('Bật loa ngoài hoặc đọc nguyên văn nhật ký tham vấn cho phụ huynh nghe',0,'Phản bội sự tin tưởng của học sinh, phá vỡ vĩnh viễn mối quan hệ tham vấn.',['empathy'=>0],1),$c('Từ chối trả lời thô lỗ và cúp máy ngang xương',1,'Gây bức xúc cho phụ huynh và tạo thêm rào cản căng thẳng trong gia đình học sinh.',['decision'=>1],2)],'Giữ vững ranh giới đạo đức bảo mật là cách duy nhất bảo vệ niềm tin của học sinh.'),
        $m(4,'trade_off','Tự chăm sóc sức khỏe tinh thần bản thân (Self-care)','Sau một ngày lắng nghe nhiều câu chuyện trầm cảm, bạn thấy trong lòng nặng trĩu và mệt mỏi.',[$c('Gặp người giám sát chuyên môn (Supervisor) để giải tỏa năng lượng tiêu cực, tập thể dục và tách rời công việc khi về nhà (Ưu tiên: Tự chăm sóc lành mạnh)',3,'Chuẩn mực vệ sinh tâm thần nghề nghiệp! Bạn giữ cho chiếc cốc năng lượng của mình luôn đầy để tiếp tục giúp đỡ người khác.',['analysis'=>3,'empathy'=>3,'decision'=>2],0),$c('Uống thuốc an thần hoặc thức trắng đêm suy nghĩ về nỗi đau của các em (Ưu tiên: Đồng hóa cảm xúc)',0,'Dễ dẫn đến kiệt sức nghề nghiệp (Burnout) và tự làm tổn hại sức khỏe tinh thần bản thân.',['decision'=>0],1),$c('Tập trở nên vô cảm, coi học sinh chỉ là những ca bệnh không liên quan đến mình',1,'Bảo vệ bản thân nhưng đánh mất trái tim thấu cảm - vũ khí mạnh nhất của người làm tâm lý.',['empathy'=>0],2)],'Người chăm sóc tâm hồn cũng cần được chăm sóc; kiệt sức trắc ẩn (Compassion Fatigue) là có thật.')
    ],['title'=>'Thực hành Lắng nghe tích cực (Active Listening)','duration'=>'15 phút','action'=>'Trò chuyện với một người bạn hoặc người thân về một khó khăn gần đây của họ trong 10-15 phút. Bạn chỉ làm 2 việc: Lắng nghe chăm chú, gật đầu và nhắc lại cảm xúc của họ (ví dụ: \'Nghe có vẻ lúc đó bạn thấy rất bất lực đúng không?\'). Tuyệt đối không phán xét, không tranh cãi và không vội vàng đưa ra lời khuyên.','reflection_question'=>'Khi bạn kìm lại được thói quen vội vã đưa lời khuyên, bạn có thấy đối phương cởi mở và giải tỏa được nhiều hơn không?']),
    'luat-su' => $game('Hồ sơ tranh chấp câu lạc bộ','Luật sư tập sự','Câu lạc bộ truyền thông bị một cựu học sinh tố cáo sử dụng trái phép chùm ảnh nghệ thuật để in ấn bán hàng. Bạn cần làm rõ chứng cứ và đề xuất phương án bảo vệ thân chủ.','Văn phòng pháp lý giả lập',[
        $m(1,'single_choice','Tiếp nhận vụ việc và gạn lọc chứng cứ','Chủ nhiệm CLB quả quyết: \'Ảnh đã đăng công khai trên Facebook thì đương nhiên thuộc về toàn dân, ai muốn lấy in gì cũng được!\'.',[$c('Tách biệt lời trần tình khỏi sự kiện pháp lý, yêu cầu cung cấp thỏa thuận ban đầu, nguồn ảnh gốc và thỏa thuận tác giả',3,'Tư duy pháp lý sắc sảo! Bạn xác định rõ bản quyền tác giả phát sinh tự động ngay khi tác phẩm được sáng tạo, không phụ thuộc vào việc đăng công khai.',['analysis'=>3,'precision'=>3,'decision'=>2],0),$c('Đồng tình ngay với chủ nhiệm CLB vì cho rằng ảnh trên mạng là miễn phí',0,'Hiểu sai căn bản Luật Sở hữu trí tuệ, đẩy thân chủ vào thế bất lợi hoàn toàn trước tòa.',['precision'=>0],1),$c('Kết luận ngay là CLB đã phạm tội hình sự lừa đảo chiếm đoạt tài sản',0,'Đánh giá quá đà, làm phức tạp hóa một tranh chấp dân sự về quyền tác giả thông thường.',['analysis'=>0],2)],'Luật sư bắt đầu từ chứng cứ và quy định pháp luật hiện hành, không dựa trên niềm tin truyền miệng.'),
        $m(1,'trade_off','Thu thập và bảo toàn chuỗi chứng cứ (Chain of Custody)','Có tin nhắn trong nhóm Zalo của CLB viết: \'Ảnh này của bạn K chụp đẹp quá, cứ lấy in bán gây quỹ đi, chắc bạn ấy không biết đâu\'.',[$c('Lập vi bằng hoặc chụp ảnh màn hình lưu giữ toàn bộ dòng thời gian tin nhắn kèm tài khoản xác thực (Ưu tiên: Toàn vẹn chứng cứ)',3,'Nghiệp vụ chứng cứ chuẩn xác! Giúp luật sư nắm chắc điểm yếu của thân chủ để chuẩn bị phương án thương lượng tối ưu.',['precision'=>3,'analysis'=>3],0),$c('Xúi giục chủ nhiệm CLB thu hồi tin nhắn và xóa vĩnh viễn nhóm Zalo để phi tang dấu vết (Ưu tiên: Tiêu hủy chứng cứ)',0,'Hành vi cản trở tư pháp nghiêm trọng, vi phạm trắng trợn đạo đức hành nghề luật sư.',['precision'=>0],1),$c('Chỉ cắt chụp một đoạn tin nhắn có lợi nhất cho mình',1,'Chứng cứ cắt xén sẽ dễ dàng bị đối phương phản bác khi họ đưa ra bản ghi đầy đủ.',['analysis'=>1],2)],'Bảo toàn ngữ cảnh trọn vẹn của chứng cứ là chìa khóa để xây dựng chiến lược pháp lý trung thực.'),
        $m(2,'single_choice','Rà soát căn cứ pháp lý (Legal Grounds)','Cựu học sinh K gửi thông báo đòi CLB bồi thường 50 triệu đồng và đăng bài xin lỗi công khai.',[$c('Đối chiếu Luật Sở hữu trí tuệ: CLB đã vi phạm cả quyền nhân thân (không ghi tên tác giả) và quyền tài sản (in bán có thu tiền)',3,'Định vị pháp lý chính xác! Nhìn rõ cả hai khía cạnh vi phạm để định giá thiệt hại thực tế tương xứng.',['analysis'=>3,'precision'=>3,'decision'=>2],0),$c('Lập luận rằng vì CLB dùng tiền gây quỹ từ thiện nên không vi phạm pháp luật',1,'Mục đích từ thiện tốt đẹp không hợp thức hóa hành vi vi phạm quyền tài sản của tác giả.',['analysis'=>1],1),$c('Lập luận rằng tác giả là học sinh thì không được pháp luật bảo vệ quyền tác giả',0,'Pháp luật bảo hộ quyền tác giả cho mọi cá nhân không phân biệt lứa tuổi.',['precision'=>0],2)],'Phân biệt quyền nhân thân (được nêu tên, bảo vệ sự toàn vẹn) và quyền tài sản (sao chép, phân phối).'),
        $m(2,'priority_order','Quy trình xây dựng chiến lược bảo vệ quyền lợi thân chủ','Bạn cần chuẩn bị văn bản tư vấn cho Ban giám hiệu nhà trường và CLB.',[$c('1. Xác định vấn đề pháp lý cốt lõi -> 2. Trích dẫn điều luật áp dụng -> 3. Đánh giá rủi ro thiệt hại -> 4. Đề xuất phương án hòa giải',3,'Cấu trúc lập luận pháp lý kinh điển (IRAC)! Báo cáo sắc bén, thuyết phục và đầy đủ luận cứ cho thân chủ.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('1. Viết tâm thư kêu gọi lòng trắc ẩn -> 2. Không cần trích dẫn điều luật',1,'Thiếu giá trị tư vấn pháp lý chuyên nghiệp, không bảo vệ được thân chủ trước rủi ro kiện tụng.',['precision'=>1],1),$c('1. Đe dọa kiện ngược lại tác giả -> 2. Không xem xét chứng cứ',0,'Chiến lược hiếu chiến mù quáng làm bùng phát khủng hoảng truyền thông của trường.',['decision'=>0],2)],'Quy tắc IRAC: Nhận diện vấn đề (Issue) -> Căn cứ pháp lý (Rule) -> Phân tích áp dụng (Application) -> Kết luận (Conclusion).'),
        $m(3,'trade_off','Lựa chọn phương án giải quyết tranh chấp','CLB đứng trước 2 ngã rẽ: Thương lượng hòa giải ngoài tòa hoặc theo đuổi vụ kiện ra tòa án.',[$c('Tư vấn phương án hòa giải: CLB công khai xin lỗi tác giả, chia sẻ một phần lợi nhuận bán ấn phẩm và ký hợp đồng bản quyền (Ưu tiên: Hòa giải cùng thắng)',3,'Quyết định của một luật sư thông thái! Dập tắt tranh chấp êm đẹp, giữ được uy tín danh dự cho cả hai bên.',['decision'=>3,'empathy'=>3,'analysis'=>2],0),$c('Khuyên CLB theo đuổi kiện tụng đến cùng để xem ai nhiều tiền hơn (Ưu tiên: Đối đầu pháp lý)',0,'Chi phí thuê luật sư và án phí sẽ vượt xa giá trị tranh chấp, gây tổn hại nặng nề cho học sinh.',['decision'=>0],1),$c('Bảo CLB cứ phớt lờ không trả lời xem bên kia có dám đi kiện thật không',1,'Thụ động và vô trách nhiệm, có thể khiến CLB bị xử thua kiện vắng mặt tại tòa.',['precision'=>1],2)],'Một thỏa thuận hòa giải tốt luôn giá trị hơn một bản án thắng kiện tốn kém kéo dài.'),
        $m(3,'single_choice','Kỹ năng đàm phán trong phiên hòa giải','Tại buổi gặp mặt, cựu học sinh K rất giận dữ và nói: \'Các bạn xem tôi như trò đùa!\'.',[$c('Chân thành ghi nhận sự cống hiến nghệ thuật của K, giải thích thiện chí khắc phục của CLB và đề xuất giải pháp tôn vinh tên tuổi tác giả',3,'Nghệ thuật đàm phán đỉnh cao! Khi cảm xúc được tôn trọng, các rào cản thỏa thuận tài chính nhanh chóng được tháo gỡ.',['empathy'=>3,'decision'=>3,'precision'=>2],0),$c('Lập tức cắt lời và cảnh cáo K: \'Bạn đang xúc phạm thân chủ của tôi, tôi sẽ kiện bạn tội vu khống!\'',0,'Kích động ngọn lửa giận dữ, đóng sập cánh cửa đàm phán hòa giải.',['empathy'=>0],1),$c('Ngồi im bấm điện thoại để hai bên tự cãi nhau',1,'Bỏ rơi vai trò người điều phối pháp lý chuyên nghiệp.',['decision'=>1],2)],'Luật sư giỏi biết lắng nghe sự tổn thương đằng sau lời giận dữ của đối phương.'),
        $m(4,'single_choice','Xung đột lợi ích (Conflict of Interest)','Bạn tình cờ phát hiện chủ nhiệm CLB chính là em họ ruột của bạn.',[$c('Công khai ngay mối quan hệ họ hàng với văn phòng luật và các bên, đề xuất cử luật sư khác chủ trì để đảm bảo khách quan',3,'Sự liêm chính nghề nghiệp tuyệt đối! Bạn bảo vệ sự trong sạch của công lý và uy tín của tổ chức hành nghề.',['precision'=>3,'decision'=>3,'empathy'=>2],0),$c('Giấu kín vì nghĩ \'người nhà thì càng phải bảo vệ vô điều kiện\'',0,'Vi phạm nghiêm trọng Quy tắc đạo đức và ứng xử nghề nghiệp luật sư.',['precision'=>0],1),$c('Ép cựu học sinh K phải rút đơn vì bạn của mình là người có thế lực',0,'Lạm dụng nghề nghiệp để chèn ép công lý, có thể bị tước chứng chỉ hành nghề.',['decision'=>0],2)],'Minh bạch và quản trị xung đột lợi ích là thước đo liêm chính hàng đầu của luật sư.'),
        $m(4,'trade_off','Xây dựng quy chế sở hữu trí tuệ cho nhà trường','Vụ việc hòa giải thành công êm đẹp trong sự hài lòng của các bên.',[$c('Soạn thảo biểu mẫu Thỏa thuận sử dụng hình ảnh và tập huấn pháp lý bản quyền ngắn cho các câu lạc bộ (Ưu tiên: Phòng ngừa thể chế)',3,'Đóng góp xã hội vô giá! Bạn biến một vụ tranh chấp thành bài học pháp luật thực tiễn cho toàn trường.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('Thu phí dịch vụ rồi đóng hồ sơ cất vào tủ (Ưu tiên: Kết thúc công việc)',1,'Hoàn thành nhiệm vụ nhưng bỏ lỡ cơ hội nâng cao văn hóa pháp lý học đường.',['decision'=>1],1),$c('Đăng chi tiết vụ việc kèm tên tuổi học sinh lên mạng xã hội để khoe thành tích thắng kiện',0,'Vi phạm bảo mật thông tin khách hàng và quyền riêng tư của vị thành niên.',['empathy'=>0],2)],'Giá trị lớn nhất của người hành nghề luật là hoàn thiện thể chế ngăn ngừa rủi ro tương lai.')
    ],['title'=>'Đọc và giải mã Điều khoản dịch vụ (Terms of Service)','duration'=>'15 phút','action'=>'Mở mục Điều khoản sử dụng (Terms of Service) hoặc Chính sách bản quyền của một nền tảng bạn đang dùng (TikTok, YouTube hoặc Instagram). Tìm xem đoạn nào quy định về quyền sở hữu hình ảnh của người dùng và nền tảng được phép làm gì với ảnh bạn đăng lên.','reflection_question'=>'Khi nhận ra mình thường ấn nút \'Đồng ý\' mà chưa từng đọc kỹ các quyền pháp lý của mình, bạn có thấy sự cần thiết của tư duy pháp luật không?']),
    'nha-bao-bien-tap-vien' => $game('Tin nóng giữa giờ trưa','Phóng viên học đường','Mạng xã hội lan truyền tin đồn trường sẽ đóng cửa một tuần vì nhiễm khuẩn nguồn nước. Bạn có 45 phút trước giờ phát bản tin trưa.','Newsroom · 11:30',[
        $m(1,'single_choice','Xác minh nguồn tin ban đầu','Một bài đăng ẩn danh trên nhóm kín có 800 lượt chia sẻ khẳng định: \'Nước trường nhiễm độc chì, chiều nay nghỉ học hết!\'.',[$c('Truy tìm nguồn gốc bài đăng, liên hệ Ban giám hiệu và phòng y tế để kiểm chứng sự thật khách quan',3,'Bản lĩnh nhà báo chân chính! Xác minh qua ít nhất hai nguồn tin có thẩm quyền trước khi đưa ra công chúng.',['analysis'=>3,'precision'=>3,'decision'=>2],0),$c('Chia sẻ lại ngay bài đăng kèm dòng chữ: \'Nghe đồn thế này, không biết thực hư ra sao\'',0,'Tiếp tay lan truyền tin giả gây hoang mang dư luận xã hội nghiêm trọng.',['precision'=>0],1),$c('Ngồi chờ xem các trang mạng khác có đăng không rồi chép lại',1,'Thụ động và thiếu trách nhiệm điều tra độc lập của người làm báo.',['analysis'=>1],2)],'Tốc độ đưa tin không bao giờ được phép đánh đổi bằng sự kiểm chứng cẩn trọng.'),
        $m(1,'trade_off','Phỏng vấn nhân chứng tại hiện trường','Một bạn học sinh đang rất hoảng loạn vì vừa uống một ngụm nước ở vòi sân trường.',[$c('Lắng nghe, trấn an em, ghi nhận triệu chứng cụ thể và đưa em vào phòng y tế kiểm tra ngay (Ưu tiên: An toàn con người & Ghi nhận khách quan)',3,'Ứng xử nhân văn và chuyên nghiệp! Bạn vừa hỗ trợ nạn nhân vừa thu thập dữ liệu xác thực.',['empathy'=>3,'precision'=>3,'decision'=>2],0),$c('Dí micro vào mặt quay clip bạn đang khóc đăng lên TikTok để câu view (Ưu tiên: Giật gân hút view)',0,'Khai thác nỗi đau và sự sợ hãi của người khác là hành vi vô đạo đức báo chí.',['empathy'=>0],1),$c('Bỏ qua không phỏng vấn vì cho rằng học sinh thì biết gì về y tế',1,'Bỏ lỡ tiếng nói của người trong cuộc chịu ảnh hưởng trực tiếp.',['empathy'=>1],2)],'Tôn trọng cảm xúc của nhân chứng nhưng phân biệt rõ ràng giữa trải nghiệm cá nhân và sự kiện thực tế.'),
        $m(2,'single_choice','Đối chiếu kết quả xét nghiệm mẫu nước','Phòng Y tế cung cấp biên bản: Một vòi nước gần bồn hoa bị vỡ ống dẫn nên có cặn đất, các vòi nước uống khác hoàn toàn an toàn.',[$c('Đọc kỹ các chỉ số xét nghiệm, chụp lại biên bản và phỏng vấn trực tiếp cán bộ y tế học đường',3,'Tư duy điều tra chính xác tuyệt đối! Bạn có bằng chứng khoa học vững chắc trong tay.',['analysis'=>3,'precision'=>3],0),$c('Chỉ nhìn lướt qua tiêu đề biên bản rồi tự suy đoán nội dung',1,'Bất cẩn dễ dẫn đến trích dẫn sai số liệu chuyên môn y tế.',['precision'=>1],1),$c('Nghi ngờ biên bản bị làm giả nhưng không liên hệ phòng xét nghiệm để xác thực',0,'Đa nghi thiếu căn cứ mà không chủ động điều tra làm sáng tỏ sự thật.',['analysis'=>0],2)],'Sự thật thường phức tạp và có sắc thái hơn một tin đồn trắng đen nhị nguyên.'),
        $m(2,'priority_order','Quy trình biên tập bản tin nóng (Breaking News)','Còn 15 phút là đến giờ phát thanh trưa của trường.',[$c('1. Sự thật cốt lõi (Không có độc chì, chỉ 1 vòi bị cặn) -> 2. Giải pháp khắc phục của trường -> 3. Lời khuyên sức khỏe cho học sinh',3,'Cấu trúc kim tự tháp ngược mẫu mực! Trấn an dư luận ngay câu mở đầu và hướng dẫn hành động rõ ràng.',['precision'=>3,'analysis'=>3,'creativity'=>2],0),$c('1. Kể chuyện lịch sử nguồn nước từ 10 năm trước -> 2. Để thông tin an toàn xuống cuối cùng',1,'Dài dòng khiến người nghe không kiên nhẫn và tiếp tục hoang mang lo sợ.',['decision'=>1],1),$c('1. Đưa tiêu đề gây sốc -> 2. Không đưa kết luận y tế',0,'Tạo ra một \'cơn bão giả\' phá hủy uy tín của bản tin học đường.',['empathy'=>0],2)],'Cấu trúc kim tự tháp ngược (Inverted Pyramid): Thông tin quan trọng nhất đặt lên đầu.'),
        $m(3,'single_choice','Nghệ thuật đặt tiêu đề (Headline)','Bạn cần đặt tiêu đề cho bài viết đăng trên website trường.',[$c('\'Trường xử lý một vòi nước bị rò cặn, bác bỏ tin đồn đóng cửa nghỉ học\'',3,'Tiêu đề chuẩn mực báo chí! Rõ ràng, trung thực, dập tắt tin đồn và cung cấp sự thật tức thì.',['precision'=>3,'creativity'=>2,'decision'=>3],0),$c('\'Khủng hoảng độc chì kinh hoàng: Học sinh toàn trường thoát chết trong gang tấc?!\'',0,'Clickbait rẻ tiền và xuyên tạc sự thật, gây phẫn nộ trong cộng đồng phụ huynh.',['precision'=>0],1),$c('\'Một thông báo bình thường không có gì đáng quan tâm\'',1,'Quá mờ nhạt khiến không ai thèm đọc để biết sự thật đã được kiểm chứng.',['creativity'=>1],2)],'Tiêu đề phải đúng bản chất ngay cả khi độc giả chỉ lướt qua mà không bấm đọc bài.'),
        $m(3,'trade_off','Áp lực thời hạn phát hành (Deadline Pressure)','Giờ phát tin đã điểm, nhưng bạn muốn chờ thêm 3 phút để phỏng vấn nốt đại diện nhà máy nước.',[$c('Phát sóng thông tin đã xác thực trước, nêu rõ: \'Chúng tôi đang liên hệ nhà máy nước và sẽ cập nhật trong bản tin sau\' (Ưu tiên: Kịp thời & Minh bạch)',3,'Xử lý tòa soạn cực kỳ chuyên nghiệp! Đảm bảo dập tắt tin đồn đúng giờ mà vẫn giữ tính minh bạch cho diễn tiến tiếp theo.',['decision'=>3,'precision'=>3,'analysis'=>2],0),$c('Hoãn phát bản tin 1 tiếng để chờ phỏng vấn xong (Ưu tiên: Cầu toàn tối đa)',1,'Tạo khoảng trống thông tin khiến tin đồn thất thiệt tiếp tục lây lan trên mạng trong 1 giờ đó.',['decision'=>1],1),$c('Tự bịa ra câu trả lời của nhà máy nước để phát sóng luôn (Ưu tiên: Làm liều cho xong)',0,'Bịa đặt phát ngôn là tội danh nghiêm trọng nhất làm sụp đổ toàn bộ sự nghiệp làm báo.',['precision'=>0],2)],'Cân bằng giữa tính kịp thời (Timeliness) và độ đầy đủ của thông tin.'),
        $m(4,'single_choice','Trách nhiệm đính chính và cập nhật thông tin','Sau khi phát sóng 1 tiếng, thợ sửa ống nước phát hiện thêm nguyên nhân do rễ cây ăn vào đường ống.',[$c('Cập nhật bài viết trực tuyến ngay lập tức, ghi rõ mốc thời gian cập nhật và lời cảm ơn bạn đọc đã cung cấp thêm chi tiết',3,'Minh bạch biên tập mẫu mực! Bạn xây dựng niềm tin sắt đá của công chúng vào tòa soạn.',['precision'=>3,'empathy'=>2,'decision'=>2],0),$c('Âm thầm sửa bài mà không ghi chú gì để tỏ ra mình luôn đúng từ đầu',1,'Thiếu minh bạch nghề nghiệp, làm giảm sự tin tưởng của độc giả kỹ tính.',['precision'=>1],1),$c('Xóa sạch bài viết cũ đi và coi như chưa từng có chuyện gì xảy ra',0,'Xóa dấu vết khiến dư luận nghi ngờ tòa soạn có sự bao che hoặc khuất tất.',['decision'=>0],2)],'Đính chính và cập nhật thông tin mới là trách nhiệm danh dự, không phải sự thất bại.'),
        $m(4,'trade_off','Bảo vệ danh tính học sinh đã tung tin đồn','Công an trường tìm ra một bạn học sinh lớp 7 vì tò mò nghịch ngợm đã viết bài tin đồn ban đầu.',[$c('Đề xuất nhà trường giáo dục nhắc nhở em nội bộ, tuyệt đối không đăng tên tuổi hay hình ảnh của em lên báo (Ưu tiên: Bảo vệ trẻ em)',3,'Lương tri của người cầm bút! Bạn phân biệt rõ giữa giáo dục một đứa trẻ với việc bêu riếu trừng phạt trên truyền thông.',['empathy'=>3,'decision'=>3,'precision'=>2],0),$c('Đăng tải toàn bộ họ tên, lớp học và ảnh chụp của em lên trang nhất để \'làm gương\' (Ưu tiên: Trừng phạt công khai)',0,'Vi phạm Luật Trẻ em và đẩy một đứa trẻ vị thành niên vào bờ vực bị bạo lực mạng.',['empathy'=>0],1),$c('Tổ chức một buổi chất vấn công khai em trước toàn trường',0,'Tạo ra sang chấn tâm lý nặng nề cho học sinh.',['empathy'=>0],2)],'Nhà báo bảo vệ công lý nhưng luôn bao dung và bảo vệ quyền trẻ em vị thành niên.')
    ],['title'=>'Thử làm chuyên gia kiểm chứng tin giả (Fact-checking)','duration'=>'15 phút','action'=>'Chọn một bài viết giật gân bất kỳ trên mạng xã hội. Áp dụng quy tắc 3 bước: 1. Ai là tác giả hoặc cơ quan phát ngôn? 2. Có trích dẫn số liệu hoặc nhân chứng có thật không? 3. Tìm kiếm từ khóa trên Google News xem các báo lớn có đăng không.','reflection_question'=>'Khi tự mình kiểm chứng nguồn tin, bạn có thấy nhiều thông tin giật gân trên mạng bị bóp méo thế nào không?']),
    'chuyen-vien-tai-chinh' => $game('Lập ngân sách ngày hội trường','Chuyên viên tài chính','Bạn quản lý ngân sách 50 triệu đồng cho ngày hội, phải cân bằng giữa trải nghiệm học sinh, an toàn và quỹ dự phòng rủi ro.','Finance Desk · 50.000.000đ',[
        $m(1,'single_choice','Lập khung ngân sách và phân loại chi phí','Các tiểu ban (Sân khấu, Ẩm thực, Trò chơi) gửi danh sách đề xuất chi tiêu tổng cộng lên tới 72 triệu đồng, vượt xa mức 50 triệu.',[$c('Phân loại chi phí thành 3 nhóm: Bắt buộc an toàn, Tạo giá trị cốt lõi, và Hạng mục xa xỉ có thể cắt giảm; chốt trần từng ban',3,'Kỹ năng quản trị ngân sách mẫu mực! Bạn biến mong muốn chủ quan thành các quyết định có căn cứ ưu tiên.',['analysis'=>3,'decision'=>3,'precision'=>2],0),$c('Chia đều 50 triệu cho các tiểu ban theo hình thức cào bằng',1,'Đơn giản dễ làm nhưng không phản ánh mức độ quan trọng và quy mô thực tế của từng ban.',['precision'=>1],1),$c('Chấp nhận hết 72 triệu rồi đi xin thêm tiền tài trợ vô tội vạ',0,'Bỏ qua cơ hội tối ưu hóa nguồn lực tài chính có sẵn trong tầm tay.',['decision'=>0],2)],'Ngân sách không phải là một con số khô khan, mà là bản đồ thể hiện thứ tự ưu tiên của dự án.'),
        $m(1,'trade_off','Đánh giá chi phí ẩn (Hidden Costs)','Tiểu ban âm thanh báo giá thuê loa đài giá rẻ bất ngờ chỉ 4 triệu đồng.',[$c('Yêu cầu bảng chi tiết: hỏi rõ đã bao gồm phí vận chuyển, công kỹ thuật viên trực và dây cáp nối hay chưa (Ưu tiên: Minh bạch tổng chi phí TCO)',3,'Cái nhìn sắc sảo của chuyên viên tài chính! Giúp tránh được \'bẫy giá rẻ\' và các khoản phụ phí phát sinh bất ngờ.',['analysis'=>3,'precision'=>3],0),$c('Ký hợp đồng ngay lập tức vì thấy giá rẻ nhất thị trường (Ưu tiên: Giá rẻ bề mặt)',1,'Vào ngày sự kiện sẽ bị đội thêm 3 triệu tiền phí vận chuyển và kỹ thuật viên.',['decision'=>1],1),$c('Từ chối luôn mà không cần hỏi thêm vì nghĩ giá rẻ chắc chắn là lừa đảo',1,'Bỏ lỡ cơ hội khảo sát một nhà cung cấp tiềm năng có thể tối ưu chi phí.',['analysis'=>1],2)],'Cẩn trọng trước những mức giá rẻ bất thường; chi phí ẩn thường xuất hiện ở phần phụ trợ.'),
        $m(2,'single_choice','So sánh và thẩm định báo giá (Procurement)','Có 3 nhà cung cấp phông bạt sân khấu gửi bảng báo giá với các điều khoản thanh toán khác nhau.',[$c('Lập bảng đối chiếu chuẩn hóa cùng kích thước, chất lượng chống cháy, tiến độ lắp đặt và điều khoản phạt chậm trễ',3,'Nghiệp vụ mua sắm thẩm định chuẩn mực! Giúp chọn được đối tác có hiệu suất chi phí (Cost-efficiency) tốt nhất.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('Chọn nhà cung cấp là người quen của một bạn trong ban tổ chức mà không cần so sánh giá',0,'Thiếu minh bạch, tạo tiền lệ xấu và tiềm ẩn rủi ro thất thoát công quỹ.',['precision'=>0],1),$c('Chọn ngẫu nhiên một bên để tiết kiệm thời gian',0,'Vô trách nhiệm với đồng tiền của tập thể giao phó.',['decision'=>0],2)],'So sánh trên cùng một mặt bằng tiêu chuẩn kỹ thuật (Apple-to-Apple comparison).'),
        $m(2,'priority_order','Quy trình giải ngân và kiểm soát tạm ứng','Các tiểu ban bắt đầu yêu cầu rút tiền mặt để đi mua sắm nguyên vật liệu.',[$c('1. Duyệt phiếu tạm ứng theo danh mục -> 2. Giải ngân tối đa 70% giá trị -> 3. Thu thập hóa đơn đỏ và đối chiếu trong 24h',3,'Quy trình kiểm soát nội bộ (Internal Controls) chặt chẽ! Ngăn ngừa hoàn toàn nguy cơ mất tiền hoặc chi tiêu sai mục đích.',['precision'=>3,'decision'=>3,'analysis'=>2],0),$c('1. Giao toàn bộ tiền mặt cho các bạn tự giữ -> 2. Cuối ngày còn bao nhiêu gom lại',0,'Rất dễ thất thoát, lẫn lộn tiền cá nhân và không thể đối chiếu sổ sách.',['precision'=>0],1),$c('1. Không cho ứng một đồng nào -> 2. Bắt học sinh tự bỏ tiền túi ra trả hết',1,'Tạo gánh nặng tài chính không công bằng cho các bạn học sinh làm công tác tổ chức.',['empathy'=>0],2)],'Quy trình kiểm soát tài chính: Phiếu tạm ứng có duyệt -> Giới hạn hạn mức -> Thu hồi hóa đơn trong 24h.'),
        $m(3,'trade_off','Xử lý phát sinh rủi ro thời tiết (Contingency Fund)','Dự báo thời tiết có 60% khả năng mưa giông; chi phí thuê mái che dự phòng là 5 triệu đồng.',[$c('Trích 5 triệu từ quỹ dự phòng rủi ro để đặt cọc mái che gấp (Ưu tiên: Bảo hiểm sự kiện an toàn)',3,'Quản trị rủi ro thông thái! 5 triệu mái che bảo vệ cho toàn bộ sự kiện 50 triệu không bị hủy hoại vì một cơn mưa.',['decision'=>3,'analysis'=>3,'precision'=>2],0),$c('Bỏ qua mái che và cầu nguyện trời sẽ không mưa để tiết kiệm 5 triệu (Ưu tiên: Đánh cược may rủi)',0,'Nếu mưa ập xuống, toàn bộ dàn âm thanh bị chập cháy và sự kiện thất bại thảm hại.',['decision'=>0],1),$c('Hủy bỏ toàn bộ ngày hội luôn để không phải lo trời mưa nữa',0,'Phản ứng cực đoan làm lãng phí công sức chuẩn bị của cả trường.',['decision'=>0],2)],'Rủi ro tài chính = Xác suất xảy ra × Mức độ tổn thất. Đừng bao giờ cắt giảm quỹ dự phòng an toàn.'),
        $m(3,'single_choice','Đánh đổi giữa mua đứt và thuê mướn (Make or Buy / Lease)','Trường cần 10 chiếc lều bạt: Mua mới giá 15 triệu (dùng được nhiều năm), thuê 1 ngày giá 4 triệu.',[$c('Thống kê nhu cầu: Nhà trường tổ chức 4 sự kiện/năm nên mua mới sẽ hoàn vốn sau 1 năm và tiết kiệm lâu dài',3,'Tư duy đầu tư vốn (CapEx) xuất sắc! Biến một khoản chi phí thành tài sản hữu ích dài hạn cho trường.',['analysis'=>3,'decision'=>3,'precision'=>2],0),$c('Cứ thuê tạm cho nhanh đỡ phải mang vác cất giữ vào kho',1,'Tiện trước mắt nhưng về dài hạn trường sẽ phải tốn hàng chục triệu tiền thuê lặp đi lặp lại.',['analysis'=>1],1),$c('Tự đi mượn bạt rách của các nhà xung quanh chắp vá lại',1,'Mất thẩm mỹ và không đảm bảo an toàn che mưa nắng.',['creativity'=>1],2)],'Phân tích điểm hòa vốn (Break-even analysis) dựa trên tần suất sử dụng thực tế của nhà trường.'),
        $m(4,'single_choice','Quyết toán và đối chiếu chênh lệch sau sự kiện','Sau ngày hội, tổng chi thực tế là 47,8 triệu đồng, còn dư 2,2 triệu đồng so với dự toán.',[$c('Đối chiếu 100% chứng từ hóa đơn, phân tích nguyên nhân tiết kiệm được 2,2 triệu và đề xuất nộp lại quỹ trường',3,'Liêm chính và chuẩn mực kế toán tài chính! Báo cáo rõ ràng tạo dựng niềm tin tuyệt đối từ thầy cô và bạn bè.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('Chỉ ghi một dòng ngắn gọn: \'Đã tiết kiệm được 2,2 triệu\' mà không kèm theo chứng từ',1,'Thiếu chứng cứ giải trình kiểm toán, dễ bị nghi ngờ về tính minh bạch.',['precision'=>1],1),$c('Lấy luôn 2,2 triệu còn dư chia nhau đi ăn liên hoan mà không báo cáo ai',0,'Hành vi chiếm dụng công quỹ trái phép, vi phạm nghiêm trọng kỷ luật tài chính.',['decision'=>0],2)],'Một con số tài chính tốt vẫn bắt buộc phải được giải trình minh bạch và trung thực.'),
        $m(4,'trade_off','Báo cáo phân tích hiệu quả tài chính (ROI)','Ban giám hiệu muốn lắng nghe báo cáo tổng kết tài chính của ngày hội.',[$c('Trình bày biểu đồ trực quan: Chi phí trên mỗi học sinh tham gia (Cost per attendee) và bài học tối ưu cho năm sau (Ưu tiên: Giá trị chiến lược)',3,'Tầm nhìn giám đốc tài chính (CFO) tương lai! Bạn cung cấp dữ liệu giá trị để nhà trường ra quyết định cho các năm tiếp theo.',['analysis'=>3,'creativity'=>3,'decision'=>2],0),$c('Chỉ đọc một danh sách dài dằng dặc các con số thu chi khiến mọi người ngủ gật',1,'Đủ số liệu nhưng thiếu khả năng truyền thông tài chính hấp dẫn.',['creativity'=>1],1),$c('Không làm báo cáo vì cho rằng sự kiện đã kết thúc tốt đẹp rồi',0,'Bỏ qua bước đóng dự án tài chính, một thiếu sót lớn trong quản trị chuyên nghiệp.',['precision'=>0],2)],'Chuyên viên tài chính giỏi biết biến những con số khô khan thành câu chuyện giá trị.')
    ],['title'=>'Lập bảng cân đối dòng tiền cá nhân (50/30/20 Rule)','duration'=>'15 phút','action'=>'Lập một bảng tính nhỏ liệt kê thu nhập (tiền tiêu vặt, tiền lì xì hoặc làm thêm) và chi tiêu trong 1 tháng. Áp dụng quy tắc quản lý tài chính kinh điển: 50% cho nhu cầu thiết yếu (ăn uống, đồ dùng học tập), 30% cho sở thích giải trí, và 20% cho quỹ tiết kiệm tương lai.','reflection_question'=>'Khi thấy rõ những khoản chi tiêu lặt vặt tích tụ lại thành số tiền lớn, bạn có thấy mình cần chủ động kiểm soát dòng tiền hơn không?']),
    'quan-tri-nhan-su' => $game('Tuyển trưởng nhóm dự án xanh','Chuyên viên nhân sự','Bạn hỗ trợ chọn trưởng nhóm cho dự án môi trường trường học, bảo đảm quy trình công bằng, giảm thiểu thiên kiến và trải nghiệm ứng viên tích cực.','People Team · 12 ứng viên',[
        $m(1,'single_choice','Xác định tiêu chí tuyển chọn (Competency Framework)','Trưởng dự án cũ nói: \'Cứ tìm ai có tính cách và phong cách giống hệt tôi là được!\'.',[$c('Chuyển đổi yêu cầu thành khung năng lực hành vi có thể quan sát: Khả năng lập kế hoạch, truyền cảm hứng và giải quyết xung đột',3,'Xây dựng tiêu chuẩn nhân sự chuyên nghiệp! Giảm thiểu thiên kiến xác nhận (Confirmation bias) và mở rộng cơ hội cho người mới.',['analysis'=>3,'precision'=>3,'empathy'=>2],0),$c('Lập tức tìm một bạn có ngoại hình và cách nói chuyện y hệt trưởng dự án cũ',1,'Rập khuôn máy móc, vô tình bỏ lỡ những ứng viên có tiềm năng đột phá theo cách riêng.',['analysis'=>1],1),$c('Chọn bạn nào có điểm học tập cao nhất lớp làm trưởng nhóm',1,'Điểm số học thuật đơn lẻ không phản ánh năng lực lãnh đạo đội nhóm.',['decision'=>1],2)],'Tuyển dụng theo cảm giác quen thuộc dễ sao chép thiên kiến cũ; hãy tuyển theo khung năng lực chuẩn.'),
        $m(1,'trade_off','Sàng lọc hồ sơ đa dạng (Diversity & Inclusion)','Có 1 ứng viên chưa từng làm cán bộ lớp nhưng có kinh nghiệm tự tổ chức nhóm cứu hộ động vật ngoài đời.',[$c('Đánh giá cao năng lực chuyển đổi: Tinh thần chủ động, vượt khó và đam mê thực tế của bạn (Ưu tiên: Đánh giá tiềm năng thực chất)',3,'Nhìn người tinh tế! Bạn nhận diện viên ngọc thô qua hành động thực tiễn thay vì chức danh trên giấy.',['empathy'=>3,'analysis'=>3,'decision'=>2],0),$c('Loại ngay từ vòng gửi xe vì chưa từng có chức danh lớp trưởng hay bí thư (Ưu tiên: Soi xét bằng cấp danh xưng)',0,'Cách lọc hồ sơ quan liêu làm mất đi những nhân tố nhiệt huyết và sáng tạo.',['empathy'=>0],1),$c('Đặc cách tuyển thẳng bạn vào luôn mà không cần phỏng vấn các bạn khác',1,'Đa dạng đáng quý nhưng vẫn bắt buộc phải tuân thủ quy trình đánh giá công bằng với mọi người.',['precision'=>1],2)],'Kinh nghiệm lãnh đạo có nhiều hình thức; hãy nhìn vào năng lực chuyển đổi (Transferable skills).'),
        $m(2,'single_choice','Thiết kế bộ câu hỏi phỏng vấn hành vi (Behavioral Interview)','Ban giám khảo đang định hỏi những câu vu vơ như: \'Em thấy mình là con vật gì nếu được chọn?\'.',[$c('Xây dựng bộ câu hỏi STAR: \'Hãy kể lại một lần em và bạn trong nhóm bất đồng ý kiến, em đã xử lý thế nào và kết quả ra sao?\'',3,'Kỹ thuật phỏng vấn hành vi đỉnh cao! Giúp ứng viên bộc lộ cách tư duy và xử lý vấn đề thực tế.',['precision'=>3,'analysis'=>3,'empathy'=>2],0),$c('Hỏi câu đố mẹo hóc búa để thử xem ứng viên có bị bối rối không',1,'Tạo áp lực vô ích và không đo lường được năng lực lãnh đạo dự án môi trường.',['creativity'=>1],1),$c('Chỉ hỏi: \'Em có chăm chỉ không?\' và hài lòng khi ứng viên trả lời \'Có ạ\'',0,'Câu hỏi đóng không mang lại dữ liệu đánh giá nào đáng tin cậy.',['analysis'=>0],2)],'Hành vi trong quá khứ là thước đo dự báo chính xác nhất cho hành vi tương lai (Mô hình STAR).'),
        $m(2,'priority_order','Quy trình chấm điểm phỏng vấn độc lập (Blind Scoring)','Các giám khảo bắt đầu tranh cãi vì mỗi người có một cảm tình riêng với từng thí sinh.',[$c('1. Chấm điểm độc lập theo bảng Rubric ngay sau phỏng vấn -> 2. Ghép điểm và xem xét độ lệch -> 3. Thảo luận đồng thuận',3,'Quy trình tuyển dụng chuẩn mực quốc tế! Triệt tiêu thiên kiến cá nhân và bảo đảm sự công bằng cho tất cả ứng viên.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('1. Giám khảo lớn tuổi nhất phán ai được là được -> 2. Các giám khảo khác không cần chấm điểm',0,'Quyết định độc đoán phá hỏng tính khách quan của hội đồng tuyển chọn.',['decision'=>0],1),$c('1. Cho các ứng viên vào biểu quyết bầu lẫn nhau -> 2. Ai được nhiều phiếu thì đỗ',1,'Dễ biến thành cuộc thi bình chọn mức độ nổi tiếng thay vì năng lực công việc.',['empathy'=>1],2)],'Cấu trúc bảo vệ tính công bằng: Chấm điểm độc lập theo thang đo -> Thảo luận đối chiếu -> Ra quyết định.'),
        $m(3,'trade_off','Cân nhắc giữa người giỏi chuyên môn và người biết kết nối','Ứng viên A cực giỏi kiến thức sinh thái nhưng ít nói và khó gần; Ứng viên B kiến thức vừa phải nhưng rất giỏi lắng nghe và đoàn kết mọi người.',[$c('Chọn Ứng viên B làm Trưởng ban điều phối, mời Ứng viên A làm Cố vấn chuyên môn kỹ thuật (Ưu tiên: Đúng người đúng việc)',3,'Nghệ thuật sắp đặt nhân sự bậc thầy! Tận dụng tối đa thế mạnh của cả hai bạn mà không ai bị bỏ rơi.',['empathy'=>3,'decision'=>3,'analysis'=>2],0),$c('Loại bỏ hoàn toàn Ứng viên A vì cho rằng người ít nói không làm được việc gì',0,'Định kiến sai lầm về người hướng nội làm mất đi một chuyên gia kỹ thuật quý giá.',['empathy'=>0],1),$c('Bắt ép Ứng viên A phải làm trưởng nhóm dù bạn rất sợ giao tiếp quản lý',1,'Đẩy người ta vào vị trí không phù hợp sở đoản dễ dẫn đến thất bại và áp lực nản lòng.',['decision'=>1],2)],'Trưởng nhóm cần năng lực kích hoạt sức mạnh của tập thể hơn là một ngôi sao cô độc.'),
        $m(3,'single_choice','Trải nghiệm ứng viên và thư từ chối tử tế (Rejection Letter)','Có 8 bạn học sinh không được chọn vào vòng trong, các bạn đang rất buồn và hồi hộp chờ tin.',[$c('Gửi thư cảm ơn chân thành, nêu rõ điểm mạnh bạn đã thể hiện và mời bạn tham gia với tư cách cộng tác viên',3,'Trải nghiệm ứng viên (Candidate Experience) tuyệt vời! Giữ trọn niềm tin và sự yêu mến của học sinh với dự án.',['empathy'=>3,'precision'=>3,'decision'=>2],0),$c('Im lặng không gửi thông báo gì, để các bạn tự hiểu là đã trượt',0,'Sự im lặng \'Ghosting\' vô cảm làm tổn thương và thể hiện sự thiếu tôn trọng công sức ứng viên.',['empathy'=>0],1),$c('Gửi email chê bai thẳng thừng các điểm yếu của ứng viên',0,'Phê bình thiếu xây dựng dập tắt nhiệt huyết cống hiến của người trẻ.',['empathy'=>0],2)],'Cách tổ chức từ chối ứng viên thể hiện rõ nhất văn hóa nhân văn của tổ chức đó.'),
        $m(4,'single_choice','Bảo mật hồ sơ cá nhân của ứng viên (HR Privacy)','Một bạn trong ban tổ chức tò mò muốn chụp ảnh bài kiểm tra tâm lý của các ứng viên gửi vào nhóm chat vui đùa.',[$c('Nghiêm khắc ngăn chặn ngay, giải thích quy tắc bảo mật hồ sơ nhân sự và khóa quyền truy cập dữ liệu',3,'Bảo vệ thông tin cá nhân chuẩn mực! Giữ gìn danh dự và sự an toàn cho các bạn tham gia tuyển dụng.',['precision'=>3,'decision'=>3,'empathy'=>2],0),$c('Cùng ngồi cười cợt xem thông tin cá nhân của ứng viên',0,'Hành vi phi đạo đức, phá hoại danh dự của người khác và làm nhơ bẩn uy tín dự án.',['empathy'=>0],1),$c('Đăng hồ sơ lên mạng để \'cộng đồng mạng cùng chấm điểm hộ\'',0,'Vi phạm nghiêm trọng quyền bảo vệ dữ liệu cá nhân.',['decision'=>0],2)],'Bảo mật dữ liệu nhân sự là đạo đức nghề nghiệp và trách nhiệm pháp lý cốt tử.'),
        $m(4,'trade_off','Đồng hành và Onboarding thành viên mới','Trưởng nhóm mới được chọn đang có phần bỡ ngỡ và lo lắng trong tuần đầu nhận nhiệm vụ.',[$c('Cùng bạn lên kế hoạch 30 ngày đầu, phân công người kèm cặp (Mentor) và tổ chức buổi gặp gỡ thân mật với cả đội (Ưu tiên: Nuôi dưỡng và Đồng hành)',3,'Chiến lược phát triển nhân tài toàn diện! Giúp thành viên mới tự tin hòa nhập và phát huy tối đa năng lực.',['empathy'=>3,'decision'=>3,'analysis'=>2],0),$c('Giao hết mọi việc rồi bỏ mặc bạn tự bơi một mình (Ưu tiên: Thử thách sinh tồn)',1,'Bỏ rơi người mới dễ khiến họ bị quá tải, lạc lõng và nhanh chóng xin từ chức.',['decision'=>1],1),$c('Làm thay toàn bộ công việc cho bạn đỡ mệt',1,'Bao bọc quá mức khiến bạn không có cơ hội trưởng thành trong vai trò lãnh đạo.',['empathy'=>1],2)],'Tuyển dụng mới chỉ là bước khởi đầu; hòa nhập (Onboarding) thành công mới tạo nên kết quả.')
    ],['title'=>'Thiết kế Bản mô tả công việc (Job Description) và Tiêu chí','duration'=>'15 phút','action'=>'Nghĩ về một vị trí câu lạc bộ mà trường bạn cần (Trưởng ban Truyền thông, Trưởng nhóm Hậu cần hoặc Lớp phó Học tập). Viết bản mô tả công việc ngắn gồm: 3 nhiệm vụ cụ thể, 3 năng lực cốt lõi cần có (ví dụ: giao tiếp, quản lý thời gian), và 1 câu hỏi phỏng vấn tình huống thực tế.','reflection_question'=>'Khi đặt mình vào vị trí người tuyển dụng, bạn có nhận thấy việc chọn đúng người đúng việc quan trọng hơn việc chỉ chọn người nổi tiếng nhất không?']),
    'ky-su-moi-truong' => $game('Điều tra dòng kênh đổi màu','Kỹ sư môi trường','Người dân báo một đoạn kênh gần xưởng thực nghiệm trường chuyển màu đen và có mùi lạ sau cơn mưa lớn. Bạn cần khảo sát có hệ thống và đề xuất giải pháp ứng phó bền vững.','Hiện trường · 07:40',[
        $m(1,'single_choice','Chuẩn bị an toàn và thiết bị lấy mẫu hiện trường','Bạn chỉ có 30 phút khảo sát trước khi trời đổ cơn mưa giông tiếp theo làm trôi mất vết ô nhiễm.',[$c('Trang bị đầy đủ đồ bảo hộ (PPE), găng tay chống hóa chất, bình chứa mẫu chuyên dụng có niêm phong và thiết bị đo nhanh pH/DO',3,'Chuẩn bị mẫu mực của kỹ sư môi trường! Bảo vệ an toàn bản thân và ngăn ngừa mẫu nước bị nhiễm bẩn chéo.',['precision'=>3,'analysis'=>2,'decision'=>3],0),$c('Chạy vội ra bờ kênh lấy nước bằng vỏ chai trà sữa uống dở',0,'Mẫu nước bị tạp chất của trà sữa làm sai lệch hoàn toàn kết quả phân tích phòng lab.',['precision'=>0],1),$c('Chỉ đứng từ xa dùng điện thoại chụp 2 bức ảnh rồi đi về',1,'Hình ảnh trực quan có ích nhưng không thể thay thế số liệu hóa lý để kết luận ô nhiễm.',['analysis'=>1],2)],'Dữ liệu môi trường có giá trị bắt đầu từ việc tuân thủ nghiêm ngặt quy trình an toàn và lấy mẫu.'),
        $m(1,'trade_off','Lựa chọn mạng lưới điểm lấy mẫu (Sampling Grid)','Dòng kênh dài 500m chảy qua xưởng thực nghiệm và khu dân cư.',[$c('Lấy mẫu tại 3 điểm: Thượng nguồn (đối chứng sạch), Điểm nghi vấn xả thải, và Hạ nguồn (đo mức độ lan truyền) (Ưu tiên: Khoa học đối chứng chặt chẽ)',3,'Phương pháp lấy mẫu khoa học kinh điển! Giúp chứng minh bằng chứng pháp lý rõ ràng về nguồn gây ô nhiễm.',['analysis'=>3,'precision'=>3,'decision'=>2],0),$c('Chỉ múc duy nhất một ca nước ở chỗ đen nhất (Ưu tiên: Nhanh gọn)',1,'Chứng minh được có ô nhiễm nhưng không chứng minh được ô nhiễm bắt nguồn từ đâu.',['analysis'=>1],1),$c('Lấy mẫu nước ở vòi nước sạch sinh hoạt trong nhà',0,'Lấy sai vị trí không giải quyết được bài toán điều tra dòng kênh.',['precision'=>0],2)],'Mẫu đối chứng thượng nguồn là chìa khóa vàng để xác định nguồn gốc điểm xả thải.'),
        $m(2,'single_choice','Đo đạc và phân tích chỉ số hiện trường','Máy đo nhanh cho thấy nồng độ Oxy hòa tan (DO) chỉ còn 1.2 mg/L (rất thấp) và pH tụt xuống 4.5 (tính axit mạnh).',[$c('Ghi nhận chỉ số, làm lạnh bảo quản mẫu ở 4°C và gửi khẩn về phòng thí nghiệm để test thêm COD, BOD5 và kim loại nặng',3,'Xử lý mẫu chuẩn xác theo TCVN! Giữ mẫu nguyên vẹn để kết quả xét nghiệm có giá trị pháp lý.',['analysis'=>3,'precision'=>3,'decision'=>2],0),$c('Khẳng định ngay trên mạng xã hội là dòng kênh đã bị đầu độc bởi chất kịch độc xyanua',0,'Phát ngôn hồ đồ thiếu căn cứ khoa học gây hoang mang dư luận xã hội.',['decision'=>0],1),$c('Đổ thêm nước lọc vào mẫu nước kênh cho màu trong bớt rồi mới đo',0,'Gian lận số liệu môi trường là hành vi vi phạm pháp luật nghiêm trọng.',['precision'=>0],2)],'DO thấp và pH axit là dấu hiệu điển hình của việc xả thải chất hữu cơ lên men hoặc nước rửa kim loại.'),
        $m(2,'priority_order','Quy trình truy vết nguồn thải (Source Tracking)','Bạn cần xác định xem dòng nước đen chảy ra từ cống xả của xưởng trường hay từ cống dân sinh.',[$c('1. Khảo sát bản đồ hoàn công hệ thống cống -> 2. Mở kiểm tra từng nắp hố ga ngược dòng -> 3. Lấy mẫu test nhanh tại điểm đấu nối',3,'Nghiệp vụ trinh sát môi trường xuất sắc! Khoanh vùng chính xác điểm phát sinh ô nhiễm mà không gây tranh cãi.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('1. Cứ thấy xưởng nào gần nhất thì đập cửa phạt tiền -> 2. Không cần xem bản đồ cống',0,'Cáo buộc vô căn cứ dẫn đến tranh chấp pháp lý và làm oan người vô tội.',['empathy'=>0],1),$c('1. Đổ thuốc nhuộm màu vào tất cả các bồn cầu trong trường xem màu chảy ra đâu',1,'Phương pháp nhuộm màu có thể dùng nhưng làm tùy tiện sẽ gây thêm ô nhiễm.',['analysis'=>1],2)],'Quy tắc truy vết: Đi ngược dòng dòng chảy -> Kiểm tra các hố ga đấu nối -> Lập sơ đồ hệ thống thoát nước.'),
        $m(3,'trade_off','Biện pháp ứng phó khẩn cấp ngăn chặn lan rộng','Dòng nước đen đang từ từ trôi ra hồ nước tự nhiên có nhiều cá sinh sống ở hạ lưu.',[$c('Thả phao quây thấm dầu, kích hoạt máy sục khí tăng oxy hòa tan khẩn cấp và đắp đập bao cát cô lập nguồn thải (Ưu tiên: Cứu hệ sinh thái hồ)',3,'Phản ứng khẩn cấp tuyệt vời! Sục khí cứu cá khỏi bị chết ngạt hàng loạt và chặn đứng dòng ô nhiễm.',['decision'=>3,'analysis'=>3,'precision'=>2],0),$c('Đổ hàng tấn hóa chất clo khử trùng mạnh xuống kênh để diệt khuẩn (Ưu tiên: Triệt tiêu vi sinh vật)',0,'Clo phản ứng tạo ra chất độc mới và tiêu diệt luôn toàn bộ phiêu sinh vật có ích trong nước.',['analysis'=>0],1),$c('Chờ đợi cơ quan quản lý họp bàn giao việc sau vài ngày',1,'Chậm trễ trong ứng phó sự cố môi trường sẽ biến một vết rò rỉ nhỏ thành thảm họa sinh thái.',['decision'=>1],2)],'Ngăn chặn sự cố môi trường lan rộng là ưu tiên cứu sinh mạng hệ sinh thái thủy sinh.'),
        $m(3,'single_choice','Giải pháp xử lý tại nguồn (On-site Treatment)','Nguyên nhân được tìm ra: Bể lắng của xưởng thực nghiệm bị nứt thành khiến bùn thải hữu cơ trào ra cống.',[$c('Đình chỉ xả thải, hút cạn bùn xử lý riêng, sửa chữa chống thấm bể lắng và lắp đặt cảm biến cảnh báo tràn tự động',3,'Giải pháp kỹ thuật triệt để và bền vững! Đảm bảo sự cố không bao giờ có cơ hội tái diễn.',['precision'=>3,'analysis'=>3,'decision'=>3],0),$c('Lắp một ống cống ngầm xả thẳng ra xa mắt người nhìn',0,'Tư duy \'xa mặt cách lòng\' vô trách nhiệm, vi phạm pháp luật bảo vệ môi trường.',['decision'=>0],1),$c('Chỉ xịt nước rửa sạch mặt đường cho đỡ mùi hôi',1,'Nước rửa lại cuốn thêm chất bẩn xuống cống khiến ô nhiễm hạ nguồn nặng hơn.',['precision'=>1],2)],'Giải pháp công nghệ môi trường phải giải quyết tận gốc nguyên nhân, không chỉ xử lý phần ngọn.'),
        $m(4,'single_choice','Báo cáo trung thực và minh bạch số liệu','Quản lý xưởng ngỏ ý nhờ bạn \'giảm bớt số đo COD trong báo cáo để trường không bị phạt tiền\'.',[$c('Kiên quyết từ chối làm sai lệch dữ liệu; báo cáo đúng sự thật kèm lộ trình khắc phục kỹ thuật khả thi để trình cơ quan thẩm quyền',3,'Khí tiết của người kỹ sư môi trường chân chính! Bạn bảo vệ sự trong lành của tự nhiên và thượng tôn pháp luật.',['precision'=>3,'decision'=>3,'empathy'=>2],0),$c('Đồng ý sửa số liệu để làm đẹp lòng lãnh đạo',0,'Tiếp tay cho hành vi hủy hoại môi trường, đánh mất tư cách của một nhà khoa học.',['precision'=>0],1),$c('Đem số liệu nội bộ chưa hoàn chỉnh bán cho các trang mạng để tống tiền',0,'Hành vi phạm pháp và tống tiền nghiêm trọng.',['decision'=>0],2)],'Sự trung thực với dữ liệu quan trắc là linh hồn và đạo đức sống còn của kỹ sư môi trường.'),
        $m(4,'trade_off','Thiết kế giải pháp sinh thái bền vững (Nature-based Solutions)','Dòng kênh đã được khơi thông an toàn, nhà trường muốn cải tạo đoạn kênh thành một công trình giáo dục xanh.',[$c('Xây dựng bãi lọc ngầm trồng cây thủy sinh (sậy, thủy trúc) để làm sạch nước tự nhiên kết hợp lối đi dạo sinh thái (Ưu tiên: Sinh thái học đường)',3,'Tuyệt tác kỹ thuật sinh thái! Biến một con mương thoát nước ô nhiễm thành phòng thí nghiệm mở sống động cho học sinh.',['creativity'=>3,'analysis'=>3,'empathy'=>3],0),$c('Đổ bê tông kín mít toàn bộ dòng kênh và đậy nắp đan lại (Ưu tiên: Cứng hóa công nghiệp)',1,'Sạch mắt trước mắt nhưng triệt tiêu hoàn toàn hệ sinh thái tự làm sạch và làm nóng đô thị.',['decision'=>1],1),$c('Thả thật nhiều hóa chất tạo màu xanh nước biển cho đẹp mắt',0,'Hành vi giả tạo và gây ô nhiễm hóa chất độc hại cho nguồn nước.',['creativity'=>0],2)],'Giải pháp thuận tự nhiên (Nature-based Solutions) mang lại giá trị sinh thái và cảnh quan lâu dài.')
    ],['title'=>'Kiểm toán rác thải sinh hoạt (Waste Audit)','duration'=>'15 phút','action'=>'Quan sát thùng rác gia đình hoặc lớp học của bạn trong một ngày. Phân loại và ghi chép tỷ lệ ước lượng: Rác hữu cơ dễ phân hủy (thức ăn thừa), Rác tái chế (giấy, chai nhựa sạch), và Rác thải nguy hại/nhựa dùng một lần. Đề xuất 1 hành động cắt giảm ngay từ nguồn.','reflection_question'=>'Khi trực tiếp nhìn thấy lượng rác mình thải ra mỗi ngày, bạn có cảm nhận được mối liên hệ trực tiếp giữa thói quen cá nhân và sức khỏe của Trái Đất không?']),
    'dau-bep' => $game('Bếp trưa 20 suất','Bếp trưởng tập sự','Bạn phải hoàn thành 20 suất cơm gà trong 45 phút, có một khách dị ứng đậu phộng nghiêm trọng và một suất ăn chay.','Bếp mô phỏng · 11:15',[
        $m(1,'single_choice','Lập kế hoạch dây chuyền sơ chế (Mise en place)','Nguyên liệu gồm thịt gà tươi, rau củ và các loại hạt còn nguyên; đơn hàng có 1 suất dị ứng đậu phộng tuyệt đối.',[$c('Đọc kỹ order, tách riêng một góc bàn sạch làm món dị ứng đậu phộng, sơ chế gà sống và rau củ trên các thớt màu khác nhau',3,'Tư duy bếp trưởng chuẩn quốc tế! Kiểm soát rủi ro nhiễm khuẩn và bảo vệ tuyệt đối an toàn tính mạng thực khách.',['precision'=>3,'analysis'=>3,'decision'=>2],0),$c('Bật bếp chiên xào ngay món dễ nhất rồi đến đâu hay đến đó',1,'Hành động vội vã khiến căn bếp trở nên lộn xộn, dễ quên các yêu cầu đặc biệt của khách.',['decision'=>1],1),$c('Dành suất dị ứng xử lý cuối cùng khi căn bếp đã ngập tràn đồ ăn thừa',0,'Để cuối cùng làm tăng nguy cơ nhiễm chéo đậu phộng lên mức cực kỳ nguy hiểm.',['precision'=>0],2)],'Mise en place tốt là bí quyết giúp căn bếp vận hành thần tốc mà không bao giờ rơi vào hỗn loạn.'),
        $m(1,'trade_off','Tách biệt khu vực chế biến món chay','Bếp có 4 bếp gas, trong đó có 1 đơn yêu cầu suất cơm chay thuần khiết.',[$c('Dùng chảo riêng, đũa gỗ riêng và dầu thực vật mới để nấu món chay (Ưu tiên: Tôn trọng trọn vẹn yêu cầu)',3,'Sự tận tâm và tôn trọng khách hàng tuyệt đối! Bạn mang lại sự an tâm trọn vẹn trong từng bữa ăn.',['empathy'=>3,'precision'=>3],0),$c('Dùng chung chảo vừa xào thịt gà nhưng tráng qua nước lã một lần (Ưu tiên: Tiện dụng bếp)',0,'Vi phạm nguyên tắc nấu ăn chay, mỡ động vật vẫn còn dính trên mặt chảo.',['empathy'=>0],1),$c('Chỉ gắp bớt thịt gà ra khỏi đĩa cơm rồi giao cho khách',0,'Hành vi lừa dối thực khách, thể hiện sự vô trách nhiệm nghề nghiệp.',['precision'=>0],2)],'Tôn trọng tín ngưỡng và lựa chọn ẩm thực của khách hàng là đạo đức của người đầu bếp.'),
        $m(2,'single_choice','An toàn thực phẩm: Ngăn chặn nhiễm khuẩn chéo','Bạn vừa dùng thớt gỗ thái thịt gà sống, đĩa dưa chuột cà chua ăn sống đang chờ thái lát.',[$c('Đổi sang thớt xanh chuyên dùng cho rau củ, rửa tay bằng xà phòng 20 giây và sát khuẩn dao trước khi thái dưa',3,'Chuẩn mực an toàn vệ sinh thực phẩm HACCP! Cắt đứt hoàn toàn con đường lây truyền vi khuẩn nguy hiểm.',['precision'=>3,'decision'=>3],0),$c('Lấy khăn lau bàn quẹt qua mặt thớt rồi thái dưa chuột tiếp cho nhanh',0,'Khăn lau bàn chứa hàng triệu vi khuẩn, biến đĩa salad thành ổ ngộ độc thực phẩm.',['precision'=>0],1),$c('Thái thật nhanh dưa chuột trước khi vi khuẩn kịp ngấm vào',0,'Tốc độ không thể ngăn được sự nhiễm bẩn vi sinh vật vô hình.',['analysis'=>0],2)],'Nhiễm khuẩn chéo từ gia cầm sống (như khuẩn Salmonella) là nguyên nhân hàng đầu gây ngộ độc.'),
        $m(2,'priority_order','Quy trình kiểm soát nhiệt độ an toàn món gà','Gà nướng trong lò thơm lừng nhưng bên trong khớp xương có thể còn chưa chín tới.',[$c('1. Dùng nhiệt kế thực phẩm cắm vào phần thịt dày nhất -> 2. Đạt 74°C trong 15 giây -> 3. Cho thịt nghỉ (Resting) 5 phút',3,'Kỹ thuật nấu nướng đỉnh cao! Gà vừa chín an toàn 100% vừa giữ được độ mọng nước mềm mại.',['precision'=>3,'analysis'=>3,'creativity'=>2],0),$c('1. Nhìn bằng mắt thấy da vàng là chín -> 2. Mang ra chặt ngay lập tức',1,'Da vàng bên ngoài nhưng bên trong có thể còn sống đỏ lòm, tiềm ẩn rủi ro ngộ độc.',['precision'=>1],1),$c('1. Nướng thật cháy đen thui toàn bộ miếng thịt gà -> 2. Để nguội ngắt rồi mới bán',0,'Làm hỏng hoàn toàn kết cấu và hương vị thơm ngon của món ăn.',['creativity'=>0],2)],'Thịt gà bắt buộc phải đạt nhiệt độ tâm (Core temperature) tối thiểu 74°C (165°F).'),
        $m(3,'single_choice','Cân bằng hương vị khi sốt bị quá mặn (Seasoning Crisis)','Nồi sốt gà chuẩn bị rưới lên cơm nếm thử thấy quá mặn do một phụ bếp lỡ tay cho thừa muối.',[$c('Thêm nước dùng gà không muối, thêm khoai tây sống thái lát để hút bớt muối và cân bằng lại bằng chút mật ong',3,'Kỹ năng xử lý khủng hoảng ẩm thực tài tình! Vừa giải cứu nồi sốt vừa giữ nguyên độ sánh ngậy đặc trưng.',['creativity'=>3,'analysis'=>3,'decision'=>2],0),$c('Đổ thêm 2 lít nước lã vào nồi sốt cho loãng ra',1,'Giảm mặn nhưng biến nồi sốt đậm đà thành một nồi canh lõng bõng vô vị.',['creativity'=>1],1),$c('Cứ thế múc rưới lên cơm phục vụ khách vì không còn thời gian nữa',0,'Món ăn quá mặn sẽ phá hỏng hoàn toàn trải nghiệm ăn uống của khách hàng.',['empathy'=>0],2)],'Chữa sốt mặn cần sự am hiểu khoa học ẩm thực: Dùng vị ngọt, chua hoặc chất tinh bột hút vị.'),
        $m(3,'trade_off','Điều phối nhịp độ bếp giờ cao điểm (Expediting)','Còn 10 phút, chuông order vang lên liên tục, 3 phụ bếp bắt đầu cuống và va vào nhau.',[$c('Hô to khẩu lệnh rõ ràng, phân định một bạn chia cơm, một bạn chặt gà, một bạn đóng gói và kiểm soát cửa ra (Ưu tiên: Nhạc trưởng giữ nhịp)',3,'Bản lĩnh chỉ huy bếp trưởng mẫu mực! Căn bếp lập tức lấy lại trật tự và hoàn thành đơn hàng đúng tiến độ.',['decision'=>3,'empathy'=>3,'precision'=>2],0),$c('Quát tháo ầm ĩ và đập nồi niêu để thúc giục mọi người làm nhanh lên',0,'Gây hoảng loạn tinh thần khiến phụ bếp càng thêm run tay và làm rơi vỡ đồ đạc.',['empathy'=>0],1),$c('Tự tay làm hết mọi việc từ xới cơm đến bưng bê và bảo các phụ bếp đứng sang một bên',1,'Bị quá tải và tắc nghẽn cục bộ ở một mình người bếp trưởng.',['decision'=>1],2)],'Bếp trưởng giỏi là nhạc trưởng giữ nhịp bình tĩnh giữa tâm bão giờ cao điểm.'),
        $m(4,'single_choice','Chốt chặn kiểm soát cuối cùng suất dị ứng','Suất cơm gà không đậu phộng đã chuẩn bị xong, nhưng đặt trên bàn chuyền cạnh một đĩa rắc vừng đậu phộng rang.',[$c('Lập tức đóng gói hộp riêng, dán nhãn đỏ cảnh báo \'ALLERGY - NO PEANUTS\', thay găng tay mới và tự tay bàn giao cho nhân viên phục vụ',3,'Trách nhiệm nghề nghiệp thiêng liêng! Bạn bảo vệ an toàn tính mạng thực khách khỏi cơn sốc phản vệ chết người.',['precision'=>3,'empathy'=>3,'decision'=>3],0),$c('Nhìn bằng mắt thấy không có hạt đậu nào rơi vào nên nhấc đĩa giao luôn',0,'Chủ quan chết người! Bụi đậu phộng siêu nhỏ bay trong không khí cũng đủ gây sốc phản vệ nguy kịch.',['precision'=>0],1),$c('Lấy ngón tay gạt một vài mảnh vụn rơi gần đó rồi giao',0,'Dầu đậu phộng dính trên tay tiếp tục làm nhiễm bẩn vào đĩa ăn.',['precision'=>0],2)],'Dị ứng thực phẩm là yêu cầu y tế khẩn cấp sống còn, không phải là sở thích ăn uống đơn thuần.'),
        $m(4,'trade_off','Giảm thiểu lãng phí thực phẩm (Zero-waste Kitchen)','Kết thúc ca ăn trưa, còn thừa nhiều đầu xương gà, cuống rau củ sạch.',[$c('Ninh xương gà và cuống rau củ làm nước dùng cốt (Stock) cho các món xúp và sốt ngày mai (Ưu tiên: Ẩm thực bền vững)',3,'Tư duy bếp bền vững tuyệt vời! Vừa tận dụng trọn vẹn dinh dưỡng, vừa giảm thiểu rác thải thực phẩm ra môi trường.',['creativity'=>3,'analysis'=>3,'precision'=>2],0),$c('Vứt toàn bộ vào thùng rác cho đỡ mất công ninh nấu',1,'Lãng phí nguồn thực phẩm giá trị và làm tăng chi phí giá vốn của nhà hàng.',['analysis'=>1],1),$c('Để nguyên trên bàn bếp đến sáng hôm sau xem có dùng được gì không',0,'Thực phẩm để qua đêm ở nhiệt độ phòng sẽ bị ôi thiu và sinh độc tố.',['precision'=>0],2)],'Đầu bếp tài hoa biến những phần thừa của hôm nay thành tinh hoa hương vị của ngày mai.')
    ],['title'=>'Nghệ thuật tổ chức bếp chuẩn bị (Mise en Place)','duration'=>'15 phút','action'=>'Chọn một món ăn gia đình đơn giản (như cơm rang, canh rau thịt băm hoặc trứng đúc thịt). Trước khi bật bếp gas, chuẩn bị tất cả nguyên liệu: thái sẵn, cân đong gia vị vào từng bát nhỏ, dao thớt xếp ngăn nắp. Bấm giờ xem việc chuẩn bị trước giúp quá trình nấu ăn nhanh và nhàn nhã thế nào.','reflection_question'=>'Cảm giác kiểm soát được toàn bộ căn bếp ngăn nắp có mang lại cho bạn sự bình tĩnh và niềm say mê sáng tạo ẩm thực không?']),
];
